INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')), 1, 'Welcome to Your Dark Side', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 1, 'The dead can talk', 'The sudden death of a priest right in front of his teenage son sends people in a frenzy. 11 years later, Nikhil Nair, a forensic expert teaching at the FBI HQ, receives coordinates of an unknown location from a mysterious source only to find out a completely mutilated, tortured and charred body back in India. With a killer responsible for a murder that can make even the toughest cops shudder on the loose, Dr. Dhananjay Rajpoot, a forensic expert is set on a wild goose chase.', 46, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 2, 'Rabbit hole', 'The investigation takes a wild turn as Dhananjay finds out the mutilated and charred body found earlier was in fact of his wife - Sandhya. But even before he could come to terms with the inconceivable loss, Dhananjay is arrested for murdering his wife. With the clock ticking, and the pressure mounting, another body with the same mask is recovered from Nagaland.', 47, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 3, 'Peek - a - boo', 'With Dhananjay behind bars, Nikhil thinks it''s all over until he gets 3 new coordinates from the same mysterious source. The killer follows the same pattern - thoroughly planned assaults targeted at random people at random locations. The chilling new development now raising more questions - Why Nikhil? And Why Now?', 36, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 4, 'Ashes from the past', 'The killer has always been a step ahead of Nikhil and Dhananjay. It''s more evident than ever as Nikhil is now trapped in killer''s custody and Dhananjay is behind bars. But what does the ruthless killer want? A perfect murder carried out by Nikhil himself! Meanwhile, Dhananjay finally figures out how it''s all connected.', 37, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 5, 'The devil has a face', 'With a merciless killer on the loose and Nikhil in his custody, the desperate CBI now turns to DJ for help. Leaving nothing to chance, DJ gets on with the investigation. Meanwhile, Nikhil is given his new murder mission. On target, Aaditya Jalan, a billionaire philanthropist.', 37, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 6, 'The firewall', 'Worried for his family, Nikhil gives in to the killer''s demand and plans to murder Aditya Jalan. But this time it''s his mentor DJ who is pulling all stops to catch the killer before it too late. It''s mentor vs protégé! Who will win the deadly game?', 38, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 7, 'Let there be darkness', '2 perfect murders down, Nikhil''s given his next target… and it''s none other than Dhananjay Rajpoot, his mentor and friend. For the sake of his family, will Nikhil murder his own mentor?', 41, '2020-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 1), 8, 'End is the beginning', 'It all boils down to the final face-off! Nikhil, Dhananjay and the killer are now involved in the battle of wits and only one will survive this sinister game.', 61, '2020-03-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')), 2, 'Rise of the Dark Side', 'Shubh returns for revenge and this season he takes the challenge to a whole new level. With the heroes fallen apart, will a desolate Dhananjay Rajpoot and a torn Nikhil Nair be able to stop him?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 1, 'The Dance of Death', 'DJ is haunted by the past & has taken refuge, hoping to outrun his demons. Nikhil is broken & blames himself for his daughter''s death. The CBI team races against time as Shubh has planned a new attack. He warns, a new world order is coming.', 59, '2023-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 2, 'The Past, the Present and the Future', 'CBI team investigates how Shubh killed those 3 people. DJ will work outside the system to catch Shubh and will go into his past, to Varanasi. Nikhil is determined to uncover the clues leading to Shubh & finds another set of coordinates.', 48, '2023-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 3, 'Burning the Forest', 'An ATF veteran, Paul takes over the case from CBI. Nikhil and him, have conflicts but will work together for the common cause. Naina comes across a mysterious portal on the dark web and DJ meets someone from Shubh''s past.', 59, '2023-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 4, 'Designing the future', 'Kesar is abducted by DJ. ATF has lost a key member & Nikhil accuses Rasul. DJ propels to dig into Rasul''s background. Despite their ideological differences, DJ joins hands with Nikhil, but Rasul has already put his evil plan in motion.', 50, '2023-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 5, 'The countdown begins', 'The CBI team is trying to rescue Nusrat against all odds. Nikhil gets a clue, but before they can discover Shubh''s plans, Rasul threatens them for Nusrat''s life. They don''t know yet that Rasul is leading them into a devious trap.', 43, '2023-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 6, 'The Domino Effect', 'ATF has to stop Shubh''s next attack. While DJ goes behind Shubh''s roots, the ATF team manages to get clues from Nusrat''s kidnapper. They all eventually realize what Shubh''s plan & attack is & how he carefully orchestrated it.', 45, '2023-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 7, 'Birth of the New God', 'The CBI members are at their lowest ebb and as they take in the ramifications, there is a hostage situation at a restaurant. While the team races against time to stop Shubh, in a stunning surprise DJ has one last trick up his sleeve.', 47, '2023-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')) AND numero_temporada = 2), 8, 'The God''s Dilemma', 'In the Titanic battle between Good and Evil, will a seemingly unconquerable Shubh fulfil his destiny and cause a complete collapse of society, or will the forces of good, against all odds, manage to prevail?', 65, '2023-06-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11912196')), 3, 'Season 3', NULL);
