INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1196946', 'The Mentalist', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0518910'), 'SERIE', 'Famous "psychic", Patrick Jane, outs himself as a fake, and using his heightened observational skills and impeccable knowledge of the human psyche, he works with the police so he can find "Red John", the madman who killed his family.', '2008-01-01', 'https://m.media-amazon.com/images/M/MV5BMTQ5OTgzOTczM15BMl5BanBnXkFtZTcwMDM2OTY4MQ@@._V1_.jpg');
