INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 1, 'Season 1', 'Patrick Jane is a celebrity psychic whose wife and child are viciously murdered by an elusive serial killer called Red John. Devastated, Patrick admits his paranormal act is fake, renounces his earlier life and uses his astonishing skills of observation and analysis - talents that made him appear psychically gifted - to bring killers to justice. At crime scenes across California, Patrick now helps an elite team of detectives break their toughest cases. But no matter how many criminals he catches, Patrick never forgets his central goal: Find Red John. And bring him down.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 1, 'Pilot', 'CBI consultant Patrick Jane, Senior Agent Teresa Lisbon and her team investigate the double murder in Palm Springs of a pro golfer''s wife and her doctor, which has the hallmarks of a serial killer with a personal connection to Jane.', 45, '2008-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 2, 'Red Hair and Silver Tape', 'While Lisbon and her team investigate the murder of a young waitress in the Napa Valley, Jane goes behind Lisbon''s back to orchestrate his own undercover operation using Van Pelt as bait.', 43, '2008-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 3, 'Red Tide', 'When a high school girl''s body washes up on the beach, Patrick Jane sets a mentalist trap in order to get her surfing friends to turn on each other and reveal what really happened.', 43, '2008-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 4, 'Ladies in Red', 'When the team learns that a wealthy investment banker found murdered inside his locked safe room was living a dual life and skimming millions from clients, Patrick Jane sets up a mental conundrum to see which of the suspects will show their true colors.', 43, '2008-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 5, 'Redwood', 'When a girl is found covered in blood and holding the murder weapon that killed her best friend, she becomes an obvious suspect, though she can''t remember anything. But Jane, believing she''s innocent, engineers a risky maneuver in which she must relive the terrifying events in order to spark her memory.', 44, '2008-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 6, 'Red Handed', 'While investigating the case of a murdered casino owner, Patrick Jane uses his mentalist skills to ultimately entrap the killer, and win big at the card tables.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 7, 'Seeing Red', 'Patrick Jane goes head-to-head with a "psychic" he suspects of murder. Intent on proving the so-called psychic is a fraud -- as well as a killer -- Jane arranges a séance to expose the murderer.', 44, '2008-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 8, 'The Thin Red Line', 'While the police suspect a drug dealer on trial is behind the murders of the State''s witness in his case, as well as his girlfriend, Patrick Jane sees a different motive for the crime -- as well as a different suspect.', 42, '2008-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 9, 'Flame Red', 'Patrick Jane suspects the only surviving member of a National Guard unit of murdering his friends - and goes undercover to prove it.', 44, '2008-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 10, 'Red Brick and Ivy', 'When a leading scientific researcher is killed by poisoning, Patrick Jane takes a personal interest in the case when he learns the prime suspect is the victim''s wife - and Jane''s former psychiatrist.', 42, '2008-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 11, 'Red John''s Friends', 'Enticed by the promise from a convicted murder that he''ll reveal information about Red John upon his release, Patrick Jane becomes singularly focused and quits the CBI in order to prove the prisoner is innocent.', 44, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 12, 'Red Rum', 'Patrick Jane sets a mentalist trap to find out who is responsible for the murder of a high school boy who antagonized the local self-proclaimed witch by killing her cat.', 42, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 13, 'Paint It Red', 'While it appears obvious that a business tycoon''s son-in-law was in on the robbery of a $50 million painting since his body is found where the painting once hung, Patrick Jane suspects others, including a Russian oil baron, an art forger and an art curator.', 43, '2009-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 14, 'Crimson Casanova', 'With Patrick Jane''s help, Cho goes undercover as a sweet-talking ladies man with all the right moves in order to catch a pick-up artist and killer with his own set of pseudo-mentalist techniques.', 44, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 15, 'Scarlett Fever', 'As Jane and the team investigate the poisoning death of the "queen bee" in a country club, they discover that the community is full of secrets, including love affairs and drug abuse', 44, '2009-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 16, 'Bloodshot', 'Patrick Jane must rely on his other senses during the murder investigation of a financial advisor when he loses his sight as a result of an explosion.', 44, '2009-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 17, 'Carnelian Inc.', 'A story of greed and betrayal pits Patrick Jane against a group of financiers when the CBI investigates a series of murders at a corporate retreat in the wilds of the Sierra Nevada foothills.', 42, '2009-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 18, 'Russet Potatoes', 'Patrick Jane and the CBI team track down a mastermind who hypnotizes people into doing their bidding.', 43, '2009-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 19, 'A Dozen Red Roses', 'Patrick Jane and the team go to Hollywood when they investigate the murder of a movie producer.', 43, '2009-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 20, 'Red Sauce', 'Patrick Jane and the CBI team investigate the murder of a mobster who was in the witness protection program.', 44, '2009-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 21, 'Miss Red', 'Patrick Jane uses his mentalist skills to play suspects off each other in order to solve the case of a wealthy software company CEO found murdered on his yacht.', 44, '2009-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 22, 'Blood Brothers', 'Patrick Jane must find a clever way to convince the troubled kids in a wilderness program to confide in him about what really happened surrounding the death of one of their peers.', 44, '2009-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 1), 23, 'Red John''s Footsteps', 'Lisbon fears that the serial killer Red John is drawing Patrick Jane into a trap when the CBI team investigates the murder of a young girl and the abduction of her twin sister.', 44, '2009-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 2, 'Season 2', 'California Bureau of Investigation consultant Patrick Jane has a blatant lack of protocol but is self-assured and driven. The former "psychic" uses his talent for seeing the clues everyone else misses to solve the most baffling crimes. But there''s more than crime: Lisbon and Cho reveal hints about their troubled pasts. Violence fells one CBI boss, and the new boss seems more interested in authority than teamwork. And as the Van Pelt-Rigsby relationship heats up, it threatens to cool down their careers.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 1, 'Redemption', 'Jane and Lisbon learn that the Red John case has been reassigned to a different CBI team led by the straight-shooting officer Sam Bosco.', 43, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 2, 'The Scarlet Letter', 'Lisbon and the team work the case of a State Senator''s murdered intern, while Jane simultaneously tries to find out what new information Bosco has uncovered on the Red John case.', 43, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 3, 'Red Badge', 'Jane, Cho, Rigsby and Van Pelt decide to conduct their own investigation when Lisbon is accused of murdering a child molester she arrested who was recently paroled.', 43, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 4, 'Red Menace', 'Jane and the CBI investigate the murder of Gordon Hodge, a powerful attorney, who is responsible for allowing a vicious murderer, Van McBride, to walk away a free man.', 42, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 5, 'Red Scare', 'Jane and the CBI team are called in to investigate the death of a prominent architect found murdered in a crumbling old mansion, and there appears to be a number of suspects.', 43, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 6, 'Black Gold and Red Blood', 'Even after Bosco arrests Jane and puts him in prison for spying on him, Jane is able to help the CBI team from his cell to solve the murder of a young man.', 43, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 7, 'Red Bulls', 'Minelli orders Patrick Jane and Lisbon and company to play nice and work together with Bosco and his team to locate a kidnapped woman being held for ransom.', 43, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 8, 'His Red Right Hand', 'The CBI team is faced with a violent and shocking crime in their own office, but must work the case in spite of their alarm of who may be behind it. Meanwhile, Rigsby and Van Pelt are definitely an "item".', 43, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 9, 'A Price Above Rubies', 'Patrick Jane and the team are called to investigate the robbery and murder of a wealthy jeweler while attending a black tie fundraiser for the CBI.', 41, '2009-12-10');
