INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 16, 'Code Red', 'When Dr. Alicia Seberg, a government research scientist, is exposed to a deadly toxin while at work and has only hours to live, she calls Patrick Jane and the CBI to find her murderer.', 43, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 17, 'The Red Box', 'Patrick and the CBI team investigate the murder of a tutor, and find a mysterious little red box near the body, starting a chain of events that turns the murder into the search for a priceless ring stolen from the British Museum. Meanwhile, Lisbon is worried when a new boss, Madeleine Hightower, takes command of the CBI, as well as mysteriously learning about Rigsby and Van Pelt''s relationship.', 43, '2010-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 18, 'Aingavite Baa', 'When a "Jane Doe" with amnesia and covered in blood steps in front of Cho and Van Pelt''s car, Patrick Jane must use all of his skills to discover who she is, her last location and why she lost her memory', 43, '2010-04-08');
