INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 21, '18-5-4', 'Patrick Jane and the CBI team investigate the death of a mathematical genius by a gun-wielding clown.', 43, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 22, 'Red Letter', 'Romantic sparks begin to fly when Patrick Jane and supposed psychic Kristina Frye cross paths again during the CBI investigation into the murder of a charismatic head of a non-profit organization that fights human trafficking.', 43, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 2), 23, 'Red Sky in the Morning', 'Patrick Jane and Kristina''s first date is interrupted by a report of Red John striking again, which is discovered to be a copycat. But when Kristina reaches out to the real Red John, both she and Jane find themselves in grave danger.', 43, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 3, 'Season 3', 'Red John strikes into the heart of the CBI. Ever since the serial killer murdered Patrick Jane''s family, the California Bureau of Investigation consultant and former faux-psychic has become obsessed with finding the man who destroyed his life. But after a homocide suspect is set ablaze in his jail cell and a CBI agent is later framed as Red John, Patrick realizes his adversary is closer than he imagined.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 3), 1, 'Red Sky at Night', 'When the CBI investigates the kidnapping of a prominent lawyer and state house lobbyist, the CBI Director wants Jane on the case, but he is uncertain of his future with the unit after his encounter with Red John.', 43, '2010-09-23');
