INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 4, 'Season 4', 'Patrick Jane was arrested for the public murder of the man he believes is the notorious serial killer Red John, who murdered his wife and daughter. Unless, of course, the man Patrick shot is someone else. With an upstart new boss, puzzling new cases, and Red John never far from his mind, the unconventional Patrick will need all his razor-sharp skills of observation, manipulative theatrics and smooth charm to sidestep the system that stands in the way of the truth.');
