INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 4), 4, 'Ring Around the Rosie', 'Jane notices a suspicious-looking man carrying a gun at a political rally and sets out to prove he''s a psychopath on the brink of committing murder. Meanwhile, Lisbon investigates the death of a photographer at the same rally.', 43, '2011-10-13');
