INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 6, 'Season 6', 'Armed with a list of seven suspects, confirmed by the killer himself, Patrick Jane and the CBI team are closing in on the elusive serial killer while continuing to solve California''s most puzzling crimes. Could Red John be a cult leader? A ghoulish forensic analyst? A super-suspicious Homeland Security Agent? Or one of four law officials, including the director of the CBI himself? The identity of the man who killed Patrick Jane''s family is finally revealed in a climactic showdown - but that''s not the end of the story! When the CBI shuttered, Jane, Lisbon and the team partner with the FBI to tackle a whole new slew of mysteries... including vicious attack on former CBI members.');
