INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 6), 18, 'Forest Green', 'When a woman is found murdered near a remote men’s social club, Jane must find a way to insinuate himself into the insular group to find the killer.', 43, '2014-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 6), 19, 'Brown Eyed Girls', 'A chance encounter with a suspicious-looking individual leads Jane and Lisbon to uncover a vast human smuggling ring. Meanwhile, Lisbon remains tempted by Pike’s offer to move to D.C. with him.', 43, '2014-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 6), 20, 'Il Tavolo Bianco', 'Jane’s freedom is at stake when a grand jury is empanelled to decide if he should be tried for the murder of Red John. Meanwhile, Lisbon tries to find out how Jane feels about the possibility of her leaving Austin with Agent Pike, and Cho and Abbott follow new leads in the human smuggling ring they recently uncovered.', 42, '2014-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 6), 21, 'Black Hearts', 'With time running out to save the victims of a kidnapping ring before they are transported overseas, Jane and Lisbon zero in on the criminal enterprise’s mastermind. Meanwhile, Lisbon decides if she will move to D.C. with Agent Pike.', 42, '2014-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 6), 22, 'Blue Bird', 'A new lead in a cold case requires Lisbon to delay her plans to leave for Washington, D.C., giving Jane time to finally come to terms with his feelings for her and decide on a course of action.', 43, '2014-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')), 7, 'Season 7', 'With serial killer Red John laid to rest, Patrick Jane is finally free to close the door on his past and plan for the future. A fresh start with the FBI has him solving top-security cases alongside former CBI agents Teresa Lisbon and Kimball Cho, new colleagues Jason Wylie and Michelle Vega, and boss Agent Dennis Abbott. And Jane''s blossoming connection with Lisbon brings a deeper bond to the partners'' already intimate and intense professional relationship. But when femme fatale Erica Flynn resurfaces from Jane''s past and another sadistic serial killer appears on the scene, affairs of the heart take a backseat to survival.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 1, 'Nothing But Blue Skies', 'Jane and Lisbon decide to keep their new relationship a secret from  their colleagues as they investigate the murder of an undercover agent.  Also, young, ambitious agent Michelle Vega joins the team.', 43, '2014-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 2, 'The Greybar Hotel', 'Lisbon goes undercover as a prison inmate in order to get a convict to turn on her boyfriend, who is the leader of a high-end car theft ring.', 41, '2014-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 3, 'Orange Blossom Ice Cream', 'Jane and Lisbon travel to Beirut where they must work with Jane''s familiar adversary Erica Flynn, who agrees to help the FBI apprehend her boyfriend, a courier for terrorist organizations, in exchange for amnesty for her past crimes.', 43, '2014-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 4, 'Black Market', 'The team investigates a murder linked to a counterfeit diamond operation, but an illness forces Jane to direct his colleagues from the office as he recuperates. Meanwhile, Abbott is concerned that transgressions in his past could harm his wife’s chance to obtain a prestigious job in Washington, D.C.', 41, '2014-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 5, 'The Silver Briefcase', 'A chance encounter with a military colonel leads Jane to believe the soldier is hiding something, leading him to dig into closed murder case of the man’s wife.', 41, '2014-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 6, 'Green Light', 'The team is brought in to consult on a botched DEA raid, but when Abbott’s former boss tries to blackmail him into keeping the agency’s missteps quiet, Abbott is forced to choose between his career and his morals.', 42, '2015-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 7, 'Little Yellow House', 'A murder investigation becomes personal for Lisbon when she learns that her underachieving younger brother, Jimmy, is being sought as a key witness.', 43, '2015-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 8, 'The Whites of His Eyes', 'Jane worries for Lisbon’s safety when the team puts itself in the line of fire to protect the witness in a murder investigation from a skilled assassin.', 42, '2015-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 9, 'Copper Bullet', 'When Abbott''s old boss, Agent Peterson, threatens Abbott''s career - and possibly his freedom - Jane devises a risky plan to protect his friend''s  future.', 41, '2015-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 10, 'Nothing Gold Can Stay', 'Jane takes extreme measures as the team tries to apprehend a deadly gang of armored car robbers before their desperation to remain free costs more innocent people their lives.', 41, '2015-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 11, 'Byzantium', 'A young man claiming to have psychic powers offers his help to the FBI in solving a pair of murders, but when he leads them to additional victims, Jane and the team begin to suspect that he is in fact the killer they''re hunting.', 42, '2015-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 12, 'Brown Shag Carpet', 'Jane agrees to once again pretend to be a renowned psychic and be used as bait in an attempt to lure out a serial killer and give the FBI a chance to apprehend him.', 41, '2015-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1196946')) AND numero_temporada = 7), 13, 'White Orchids', 'Lisbon accepts Jane''s surprise marriage proposal, but a killer''s quest for revenge may cost them the happy ending they''ve worked so hard to achieve.', 42, '2015-02-18');
