INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')), 1, 'Season 1', 'Panchayat is a comedy-drama, which captures the journey of an engineering graduate Abhishek, who for lack of a better job option joins as secretary of a panchayat office in a remote village of Uttar Pradesh.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 1, 'Gram Panchayat Phulera', 'An unwilling Abhishek Tripathi reaches Phulera to join as panchayat secretary of the village panchayat office. However, his first day at work turns out to be far worse than what he imagined.', 35, '2020-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 2, 'Bhootha Ped', 'As frequent power cuts hamper Abhishek''s CAT preparation, he decides to take the matter in his own hands. Little did he know what he''s up against.', 33, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 3, 'Chakke Wali Kursi', 'To make his life easier Abhishek buys a new comfortable chair, which has "wheels". In the process, he unknowingly ends up disrupting the panchayat office''s power balance.', 30, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 4, 'Hamara Neta Kaisa Ho?', 'Under severe pressure to implement a government scheme, Abhishek pushes Pradhan Ji to make an extremely unpopular move. Will Pradhan Ji bow?', 25, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 5, 'Computer Nahi Monitor', 'Bored with his mundane life, Abhishek decides to have a little bit of fun. But sometimes with great fun comes grave consequence.', 33, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 6, 'Bahot Hua Samman', 'To focus on his studies, Abhishek decides to put aside his ego. But for how long?', 23, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 7, 'Ladka Tez Hai Lekin..', 'Finally, the much-awaited CAT exam is around the corner. As Abhishek juggles between his work and studies, Pradhan Ji sees him as a potential groom for his daughter. Is he the right choice?', 30, '2020-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 1), 8, 'Jab Jaago Tabhi Savera', 'Demotivated by his performance in CAT, Abhishek tries to come at peace with his reality. However, motivation comes to him in the most unexpected way.', 36, '2020-04-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')), 2, 'Season 2', 'With the rise of an opponent against Pradhan Ji, village politics of Phulera heats up. Unable to stay neutral, Abhishek sticks his neck out for Pradhan''s family.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 1, 'Naach', 'Abhishek tries to save a deal derailed by an overenthusiastic Manju Devi. Prahlad and Vikas struggle with their doubts about Abhishek and Rinki.', 43, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 2, 'Bol Chaal Band', 'Due to lagging village development work, a political opposition starts to emerge against Pradhan Ji. Abhishek''s loyalty gets tested.', 36, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 3, 'Kranti', 'Abhishek gives pace to the village development work. But not without hindrance.', 31, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 4, 'Tension', 'On a slow office day Abhishek and Vikas find themselves in an unusual situation. It''s a big day for Pradhan''s family.', 36, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 5, 'Jaise Ko Taisa', 'Political opposition against Pradhan''s family takes its final shape. Abhishek picks a side, loud and clear.', 29, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 6, 'Aukaat', 'A desperate Pradhan Ji makes an attempt to full-fill his biggest election promise. Abhishek gets a reality check, but in a harsh way.', 35, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 7, 'Dost Yaar', 'Abhishek questions his importance in Pradhan''s team. Pradhan Ji and Manju Devi have their own dilemmas.', 35, '2022-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 2), 8, 'Parivaar', 'Afraid of losing the perception battle to his political opponent Pradhan Ji makes a tough call. An upset Abhishek tries to emotionally detach himself from the people around.', 46, '2022-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')), 3, 'Season 3', 'As the Panchayat elections approach, both Pradhan and Bhushan gangs engage in a fierce battle to uplift their public image. Navigating the murky waters of Phulera politics, Abhishek does his best to maintain his objectivity.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 1, 'Rangbaazi', 'Pradhan''s desperate attempt to prevent Abhishek''s impending transfer intensifies the conflict between the Pradhan gang and the MLA. Prahlad finds it difficult to make peace with his new reality.', 48, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 2, 'Gaddha', 'Abhishek returns with the resolve of staying away from the village politics. Fearing the loss of public reputation, Pradhan and Manju Devi need Abhishek''s help to handle a rebel.', 41, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 3, 'Ghar Ya Eent-Patthar?', 'After Bhushan senses an opportunity to attack Pradhan, Abhishek jumps into damage control mode. Prahlad doesn''t like the way Pradhan uses Abhishek for political benefit.', 35, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 4, 'Atma Manthan', 'The final blow to Pradhan''s reputation comes after he gets accused of partiality in a welfare scheme implementation. Meanwhile to topple Pradhan''s rule, Bhushan allies with the MLA.', 34, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 5, 'Shanti Samjhauta', 'Manju Devi reluctantly agrees to Bhushan''s proposal of entering into a peace agreement with the MLA. Abhishek too gives his nod as it''s impossible to get the road built without MLA''s support.', 36, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 6, 'Chingaari', 'To fix their dented image, the Pradhan gang sets a trap to capitalize on a lethal mistake committed by the MLA. Amidst all the political chaos an unexpected news brings joy to the Pradhan gang.', 35, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 7, 'Shola', 'Fully aware of his actions, MLA not only walks into the trap but also raises the stakes. Pradhan gang needs to walk the talk or it''s all over.', 35, '2024-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 3), 8, 'Hamla', 'Finally, Pradhan rallies the whole Phulera behind him to fight one last battle for glory. Abhishek finds himself too deep into the murky waters of village politics and loses his objectivity.', 50, '2024-05-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')), 4, 'Season 4', 'Amidst the much-awaited village panchayat elections, Pradhan’s and Bhushan’s camps battle tooth and nail to maintain the upper hand. The future of everyone, including Abhishek, hangs in the balance.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 1, 'Case-Mukadma', 'Abhishek fears the police case for slapping Bhushan could ruin his career. Drunk and frustrated, he vents and tries to apologise, hoping Bhushan will drop the case. But Bhushan has other plans because he wants Abhishek’s help to clear his name in the Pradhan shooting. The situation escalates when the MLA also gets involved in the deal.', 38, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 2, 'Zakhm', 'Pradhan, a survivor of an "assassination" attempt, tries to leverage sympathy as he kicks off his election campaign. His team organises a public event where he cleans a dirty village spot despite being wounded. Meanwhile, Bhushan’s camp makes a pre-emptive strike to steal Pradhan’s thunder and gain the upper hand.', 33, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 3, 'Vachan', 'After noticing a crack in Bhushan’s camp, Pradhan sees an opportunity to weaken his rival. Following his instructions, his team tries to break the unity of Bhushan’s camp by targeting one of his key loyalists. But the plan does not go as smoothly as hoped. Loyalties run deep, and winning him over proves more difficult than expected.', 31, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 4, 'Shakti Pradarshan', 'While Pradhan and Manju Devi prepare for a grand nomination, Bhushan and the MLA hatch a plan to humiliate Pradhan''s family in front of the villagers. Acting on a secret tip, a team of government officials pays a surprise visit to members of Pradhan’s camp.', 36, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 5, 'Ashirvaad', 'A few days before the election, Manju Devi''s father visits Phulera to bless his daughter. During a door-to-door campaign, a physical altercation breaks out between rival camps after Kranti Devi insults Khushbu, Vikas’s pregnant wife, deeply offending both Prahlad and Vikas.', 34, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 6, 'Sanjeevani', 'Jealous of Bhushan gaining strong support in the village, Pradhan’s camp grows anxious. A temporary reprieve comes when the local MP, the MLA’s superior, offers a chance to solve their problems. However, this opportunity comes with a twist, creating a moral dilemma among the camp members, especially Prahlad.', 34, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 7, 'Dramabaaz', 'Just before election day, the local electricity transformer malfunctions, causing a power outage across the village. Pradhan’s camp scrambles to get it repaired but faces a dilemma when they learn where the electrician is from. Meanwhile, Bhushan’s camp prepares to deliver the final blow to Pradhan’s campaign.', 46, '2025-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')) AND numero_temporada = 4), 8, 'Dabdaba', 'As Abhishek plans his next move after receiving his CAT results, Pradhan’s family anxiously awaits the election outcome. The advance order of sweets becomes both a topic of conversation and a subtle display of confidence. While both factions try to project strength before the villagers, the MLA keeps a sharp eye on Phulera’s political future.', 46, '2025-06-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12004706')), 5, 'Season 5', NULL);
