INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 1, 'Season 1', 'A murder-mystery writer and a detective team up to catch a serial killer who is reenacting murders from his books. Once the case is solved, the unlikely pair continue to work together to probe New York City''s most unusual homicides.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 1, 'Flowers for Your Grave', 'Author Richard Castle joins NYC Detective Kate Beckett to help solve the case of a serial killer who is reenacting murders from Castle''s novels; Castle becomes very intrigued with the murders and continues to shadow Beckett, much to her chagrin.', 44, '2009-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 2, 'Nanny McDead', 'When a body of a young woman is found inside the dryer at a laundry room, Castle and Beckett uncover that the young woman worked as a nanny in the upscale building. Meanwhile, as Castle works on his "Nikki Heat" novel series he watches Beckett''s actions as she works the murder case.', 42, '2009-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 3, 'Hedge Fund Homeboys', 'When a teenaged boy whose family has recently fallen on hard times is found dead in a boat in Central Park, Castle and Beckett must piece together the mystery behind the boy''s final moments. Meanwhile, Castle mulls over leaving Martha home while he chaperones Alexis'' trip to Washington, D.C.', 42, '2009-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 4, 'Hell Hath No Fury', 'The investigation behind a body found wrapped in a rug on the sidewalk leads Castle and Beckett deep inside the world of New York City politics. The partners discover a world of expensive escorts, arrogant tycoons, corrupt investigators, and the effects of betrayal.', 43, '2009-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 5, 'A Chill Goes Through Her Veins', 'Castle and Beckett investigate the murder of a women found frozen and tangled in steel bars at a construction site. The case leads them to look into an old case and also has Beckett thinking about some memories of her past.', 44, '2009-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 6, 'Always Buy Retail', 'A man is killing people and posing them in Vodun (Voodoo)  tradition. Castle''s ex-wife announces her plans to move back to New York.', 43, '2009-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 7, 'Home Is Where the Heart Stops', 'After discovering a young woman''s body stuffed awkwardly into a jewelry safe, Beckett and Castle investigate numerous cases involving murders and home invasion jewel heists.', 43, '2009-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 8, 'Ghosts', 'Castle and Beckett investigate the murder of a woman found drowned in motor oil in a motel bathtub. They seek the help of a true crime journalist who might have a connection to the victim.', 44, '2009-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 9, 'Little Girl Lost', 'When a two-year-old girl is discovered missing from her home, Beckett is called in to assist with the investigation only to discover that the FBI agent in charge is, in fact, her ex-boyfriend. The two of them try to put aside their unresolved feelings as they race to find the girl, but when Castle inserts himself into the investigation, competition quickly heats up for Beckett’s attention.', 44, '2009-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 1), 10, 'A Death in the Family', 'Castle and Beckett investigate the murder of a missing plastic surgeon who is found dead in the front seat of his car after a week of being parked curbside. As they delve into the twisted world of surgery obsessed patients and secret operations, Castle experiences a fatherly rite of passage as Alexis attends her first prom. And while looking into Beckett’s past, he unearths information that could end his relationship with her forever.', 44, '2009-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 2, 'Season 2', 'Best-selling mystery novelist Rick Castle’s unique approach to crime solving may have won over Detective Kate Beckett, but after crossing her, Castle is going to have to do his best work to get her back on his side.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 1, 'Deep in Death', 'When the new season begins, Castle is wrestling with how to repair his relationship with Beckett, while struggling to finish his soon-to-be-published bestseller, Heat Wave. But circumstances force the pair back together to investigate the mysterious murder of a man found dead, tangled in the limbs of a tree.', 42, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 2, 'The Double Down', 'When two separate murders are committed on the same night, Castle wagers Ryan and Esposito that he and Beckett will solve theirs first. The frenzied race to catch their respective killers and win the bet leads each investigative duo to a likely suspect, only to find that they both have airtight alibis. But bizarre twists in both cases force the two teams to work together to unravel the mind-bending mystery behind each murder.', 43, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 3, 'Inventing the Girl', 'Castle and Beckett get an inside look at the cutthroat world of the New York fashion industry when they investigate the brutal murder of a young model during Fashion Week.', 44, '2009-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 4, 'Fool Me Once', 'When an Arctic explorer is killed during a polar expedition, the mysterious circumstances of his death take Castle and Beckett from the penthouses of Park Avenue to the halls of the CIA. But Castle''s delight at the case''s many twists and turns soon turns to frustration as he realizes that their elusive killer might just be fooling them all.', 44, '2009-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 5, 'When the Bough Breaks', 'Castle has a new book agent, Paula Haas, who tells him of an exciting opportunity that may change his career. The downside is that taking the opportunity would mean the end of his relationship with Beckett. Meanwhile, an unidentified woman is found dead in a manhole.', 44, '2009-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 6, 'Vampire Weekend', 'As Halloween approaches, Castle and Beckett are called to a graveyard where the body of a young man sporting vampire fangs has been discovered with a wooden stake driven through his heart. Their investigation takes them deep into the heart of New York''s underground vampire fetish community, where they learn that the motive for the victim''s murder may be hiding within the pages of the graphic novel he was writing before his death.', 44, '2009-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 7, 'Famous Last Words', 'An up-and-coming rock star''s body is found in a scene that appears staged from her recent music video.', 44, '2009-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 8, 'Kill the Messenger', 'After a bike messenger, carrying a package with content that is able to free a wrongly convicted man from prison, is brutally murdered, Castle and Beckett need to investigate the case. But they are surprised to find out that the tragic death is linked to another murder case previously investigated by Captain Montgomery. Now, in order to solve the new murder, Castle and Beckett must dig deep and discover all the secrets of a prominent New York family.', 44, '2009-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 9, 'Love Me Dead', 'Castle and Beckett are thrust into the world of ex-cons and escorts. Meanwhile, Alexis has a private chat with Beckett about something that she''s keeping from her father.', 42, '2009-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 10, 'One Man''s Treasure', 'When a murdered man is found stuffed in the garbage chute of an apartment building and two women arrive to ID his body — one his wife and the other his fiancee — Castle and Beckett have their hands full keeping the women from killing each other as they work to peel back the layers of the victim''s double life. Was it a jilted woman, corporate espionage, or a much darker secret that led to his demise?', 44, '2009-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 11, 'The Fifth Bullet', 'Castle and Beckett uncover that a bullet is missing from the crime scene while investigating what happened when an art dealer was gunned down in his own gallery. However, when it turns out there was a witness to the murder, they need to refresh the man''s memory, only to find out that he suffers from amnesia and can''t even remember who he is.', 44, '2009-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 12, 'A Rose for Everafter', 'When Castle and Beckett are called to a wedding to investigate the death of a bridesmaid, Castle is stunned to discover that the soon-to-be bride is his old flame, Kyra, "the one that got away". Complications ensue as Kyra, caught off-guard by Castle''s reappearance in her life, wonders if she''s marrying the right guy. With the nuptials forestalled and the entire wedding party under suspicion, Beckett questions Castle''s ability to be objective about the case. But when it looks to Beckett like Castle and Kyra might rekindle their romance, her judgment may be compromised as well.', 43, '2010-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 13, 'Sucker Punch', 'While investigating the death of an Irish mobster, Beckett and Castle uncover a local turf war that may be connected to both a late-night infomercial guru and an international drug smuggling operation. But the case turns agonizingly personal when evidence emerges that the killer they''re chasing may have had a hand in Beckett''s mother''s murder.', 44, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 14, 'The Third Man', 'Mysteries abound when a family returns from vacation to discover a dead man in their daughter''s bed. Thinking they''re investigating the murder of a squatter, Castle and Beckett soon find themselves unraveling a multi-million dollar heist. Meanwhile, Castle tries to keep Beckett from finding out that they''ve been romantically linked when he''s featured as one of New York''s 10 most eligible bachelors.', 44, '2010-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 15, 'Suicide Squeeze', 'A beloved former major league baseball player is found dead after a goodwill trip to Cuba. The investigation, which includes running into Joe Torre, leads the detectives into New York''s Cuban community to solve the murder. Meanwhile, Alexis'' genealogy project forces Castle to consider the identity of his unknown father.', 44, '2010-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 16, 'The Mistress Always Spanks Twice', 'When a half-naked woman is found covered in caramel sauce and hanging by bondage cuffs in a public park, Castle and Beckett''s investigation takes them into New York''s underground world of sexual domination. Naturally the case serves as sexy fodder for their already charged relationship banter.', 43, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 17, 'Tick, Tick, Tick... (1)', 'Federal Agent Jordan Shaw, an insightful and accomplished Federal investigator teams up with Castle & Beckett to hunt down a cunning and elusive serial killer.', 43, '2010-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 18, 'Boom! (2)', 'In the second part of the story begun in "Tick, Tick, Tick," the serial killer remains at large and is taunting Castle, Beckett and Jordan Shaw to catch him', 44, '2010-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 19, 'Wrapped Up in Death', 'The investigation into the shocking death of a museum curator, crushed by a falling gargoyle, takes a bizarre turn when Castle and Beckett learn that he isn’t the first member of a recent archeological expedition to die. It turns out there was a legend inscribed over the burial chamber the team unearthed warning that “all who gaze upon the face of the mummy are doomed.” Was the curator just the latest victim of “The Mummy’s Curse”? And if so, what does that mean for Castle, who snuck a peek at the mummy when no one was looking?', 44, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 20, 'The Late Shaft', 'When Castle appears on a late-night talk show to promote his book, Heat Wave, legendary host Bobby Mann leans in during a commercial break and whispers, "They want me dead." When Mann dies later that night, seemingly of natural causes, Castle has to convince Beckett that there was foul play. During the investigation, Castle is seduced by a Hollywood hottie, who was the other guest on Bobby Mann''s show the night he died.', 44, '2010-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 21, 'Den of Thieves', 'Investigating the murder of a thief, Castle and Beckett are surprised to learn that Esposito has a personal connection to the suspected killer. Another surprise is in line for Castle when Beckett hits it off with the handsome Robbery detective assigned to the case, Tom Demming. Now this romantic triangle must work together to solve the case', 44, '2010-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 22, 'Food to Die For', 'A high profile chef is found frozen to death in the kitchen of a hot New York restaurant. Complications ensue when Castle and the restaurant owner, an old high school girlfriend of Beckett''s, share an attraction. Meanwhile, Beckett''s relationship with Det. Demming continues to grow.', 44, '2010-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 23, 'Overkill', 'A robbery-homicide prompts Beckett to invite Demming to assist on a case, giving Castle a ringside seat to their budding romance. When it becomes clear that the two men have very different ideas about how to proceed, the investigation becomes an unspoken competition for Beckett''s attention, one in which each man races to solve the case, as Beckett referees between her two admirers.', 44, '2010-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 2), 24, 'A Deadly Game', 'Nothing is as it seems when Castle and Beckett investigate what appears to be the assassination of an intelligence operative. Meanwhile, Beckett''s romance with Demming threatens her relationship with Castle, forcing them to confront their feelings for each other.', 44, '2010-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 3, 'Season 3', 'She’s still armed. He’s still dangerous. And their chemistry is hotter than ever. Season three finds both Richard Castle and Detective Kate Beckett pursuing romantic options of their own. Their signals may be crossed, but this duo hasn’t lost any of their spark. With Beckett’s intrepid police work and Castle’s uncanny insight, solving murder has never been so much fun. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 1, 'A Deadly Affair', 'When Beckett and her team burst into an apartment on a murderer''s trail, they see Castle standing over a dead woman''s body holding a gun; Beckett arrests Castle as he asserts his innocence.', 44, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 2, 'He''s Dead, She''s Dead', 'Beckett and Castle search for a psychic''s killer while debating the existence of extrasensory abilities.', 44, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 3, 'Under the Gun', 'When a coded document attracts Castle''s attention, Beckett must steer the case back to the violent felons who populated their victim''s world; when Beckett''s ex-partner arrives, Castle must watch the relationship become romantic.', 44, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 4, 'Punked', 'Castle and Beckett look into the murder of a young mathematician gunned down with a 200-year-old bullet, sparking some wild theories by Castle about a time-traveling killer. When their investigation uncovers a tricked-out DeLorean and a suspect in Victorian clothing, is it possible Castle''s crazy idea has some validity? This winding tale twists through the towers of Wall Street and into the world of a secret steampunk society that embraces the romance and simplicity of the past, while coupling it with the hope and promise of the future.', 44, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 5, 'Anatomy of a Murder', 'An unknown woman falls out of a casket along with the original deceased when pallbearers lose control of the casket at a funeral; the investigation takes Beckett and Castle into the world of amorous, bed-hopping physicians.', 44, '2010-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 6, '3XK', 'When a beautiful woman is found dead in an alley, all clues point to her being a victim of the notorious Triple Killer. The Triple Killer, or 3XK, terrorized New York City four years ago, then mysteriously disappeared. Now he''s back. In a deadly battle of wits, Castle and Beckett race against time to stop 3XK before he claims his next victims.', 44, '2010-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 7, 'Almost Famous', 'An "Officer Down" call turns out to be a male stripper dressed like a cop. Castle and Beckett explore the world of male strip clubs and struggling actors, all people in pursuit of fame. They need to determine if the murder was because of the victim''s dreams of stardom or something more sinister.', 43, '2010-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 8, 'Murder Most Fowl', 'Castle and Beckett investigate the murder of an NYC subway worker found shot in Central Park. But, while investigating the murder they uncover the abduction of a young boy as well. The team must determine the motives behind the high stakes kidnapping in order to save the young boy''s life.', 44, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 9, 'Close Encounters of the Murderous Kind', 'Castle''s latest theory is alien abduction after an astrophysicist''s death is found to be from explosive decompression. A well know alien abduction expert gets involved in the case. To complicate things more, a government agent wants to shut down their investigation.', 43, '2010-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 10, 'Last Call', 'Castle and Beckett investigate the murder of a dockworker turned bar owner who''s body is found floating in the East River. In the process of the investigation they uncover a secret buried since the days of Prohibition.', 44, '2010-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 11, 'Nikki Heat', 'When Castle''s novel ''''Heat Wave'''' becomes a movie, actress Natalie Rhodes accepts Beckett''s invitation to visit and learn about the character she will play; Natalie observes Castle and Beckett''s investigation of the murder of a matchmaker.', 43, '2011-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 12, 'Poof! You''re Dead', 'Castle and Beckett investigate the murder of the owner of a historic magic shop found dead in a Houdini''s water torture tank.', 44, '2011-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 13, 'Knockdown', 'When the detective who investigated Beckett''s mother''s murder is shot before Beckett''s eyes before he can give her new evidence in the case, Beckett''s old wounds are reopened. The investigation of the detective''s death leads the team to an old scheme which may provide the answer to why Beckett''s mother was murdered and who ordered it. Beckett and Castle''s relationship takes a new turn.', 44, '2011-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 14, 'Lucky Stiff', 'The brutal murder of a lottery winner has Castle and Beckett up to their eyeballs in suspects, envious and angered by the victim''s sudden move from the poorhouse to the penthouse. As the precinct buzzes with fantasies of what our cops would do if they won the lottery, Martha struggles with the reality of such a decision when she suddenly inherits money she feels she doesn''t deserve.', 44, '2011-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 15, 'The Final Nail', 'Castle and Beckett find themselves on opposite sides of the case when Castle''s old school friend emerges as the prime suspect in his own wife''s murder. As they work to solve the crime, Castle comes to realize that one of two terrible things must be true... Either Detective Beckett is about to arrest an innocent man for murder, or his old friend is a cold-blooded killer.', 44, '2011-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 16, 'Setup (1)', 'Castle and Beckett investigate the apparent robbery-homicide of a New York cab driver, only to discover that the victim was involved in a mysterious conspiracy with unimaginable consequences. As the stakes continue to rise, hard-charging federal agent Mark Fallon takes over the investigation. Together, Fallon, Beckett and Castle must race to unmask the truth about the victim before it''s too late.', 44, '2011-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 17, 'Countdown (2)', 'With time running out, Castle and Beckett must put aside their differences with Agent Fallon to avert a city-wide catastrophe.', 44, '2011-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 18, 'One Life to Lose', 'A murder has been committed on the set of "Temptation Lane", one of New York''s longest running soap operas.', 44, '2011-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 19, 'Law & Murder', 'During the high profile trial of a murdered socialite, a juror tumbles out of the jury box....dead.', 44, '2011-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 20, 'Slice of Death', 'When a reporter is found dead inside a restaurant''s pizza oven, Beckett and Castle go to work on solving the case. They must figure out if his story "The Pizza Wars" is what got him killed or if there''s something more to the story.', 44, '2011-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 21, 'The Dead Pool', 'When a champion swimmer and Olympic hopeful is found dead in a training pool, Castle & Beckett dive in to investigate his murder, and uncover myriad secrets that might have led to his death.', 44, '2011-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 22, 'To Love and Die in L.A.', 'While investigating the shooting death of her ex-partner in New York, Beckett comes to believe the suspect has fled to Los Angeles. Against orders, she travels to L.A., going renegade to track down the killer, with Castle unexpectedly along for the ride. As they dig deeper into the motives, they uncover a trail that leads from a rooftop pool in Hollywood to the sandy beach of Santa Monica. Along the way, they visit the set of the "Heat Wave" movie (based on Castle''s book) and enlist the cast to help break the case. But as they get closer to apprehending the killer, Castle begins to wonder whether Beckett is out for justice or revenge.', 44, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 23, 'Pretty Dead', 'During rehearsal for "Baron''s All-American Beauty Pageant," the contestants are shocked to discover the body of Miss Illinois - strangled, but by whom? As Castle and Beckett delve into the cut-throat competition of the pageant world, they learn that a number suspects had motive for murder, including jealous fellow contestants, the pageant''s larger-than-life millionaire sponsor, Victor Baron, and the show''s host -- hedonistic TV personality, Bobby Stark.', 43, '2011-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 3), 24, 'Knockout', 'Kate Beckett''s investigation into her mother''s death is reactivated when Hal Lockwood - a professional hitman with knowledge of Beckett''s mother''s murder - stages a spectacular escape during a court hearing. As police launch a manhunt for Lockwood, Castle and the team uncover evidence of a deeper conspiracy involving a mysterious figure with law enforcement connections who is linked to both Lockwood''s escape and the killing of Johanna Beckett. The search for Lockwood and the quest to identify his co-conspirator leads to a shocking and deadly conclusion.', 44, '2011-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 4, 'Season 4', 'Prepare for a season full of suspense as Castle works to identify Beckett''s shooter while Beckett struggles with the aftermath of her near-death encounter. All the while, the duo tackles a new batch of New Your City''s most interesting cases.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 1, 'Rise', 'Detective Beckett  fights for her life as Castle, plagued by guilt over his role in the events, struggles to uncover who''s behind her brutal shooting. Meanwhile, back at the precinct, Ryan and Esposito have to adjust, as Victoria "Iron" Gates becomes the precinct''s new uncompromising Captain.', 44, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 2, 'Heroes & Villains', 'When an ex-con is mysteriously slain in an alley, Castle and Beckett believe a vigilante is behind the murder. But efforts to identify their suspect are thwarted when they discover that he roams the city in a Superhero costume – and may indeed be a Superhero. Can they capture and unmask the killer before he strikes again?', 44, '2011-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 3, 'Head Case', 'A murder scene complete with lots of blood but no victim and high tech life-extension science are all part of the investigation as Castle and Beckett try to solve a murder without a body. Meanwhile, Alexis waits to hear news about her application to Stanford', 44, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 4, 'Kick the Ballistics', 'While investigating the mysterious shooting death of a young woman, Castle and Beckett face a cop''s worst nightmare when they discover that the gun used in the killing is Det. Ryan''s old service weapon - the one that was stolen by the serial killer, 3XK. Now with the clock ticking, the team must work to solve the murder, track down 3XK and retrieve Ryan''s gun before the killer strikes again.', 44, '2011-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 5, 'Eye of the Beholder', 'A wealthy museum patron is a suspect when a valuable sculpture is stolen. Castle and Beckett investigate the theft with the help of an insurance investigator who sets her sights on Castle.', 44, '2011-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 6, 'Demons', 'While doing some investigative work at a New York mansion, a prominent ghost hunter is murdered. Castle and Beckett must figure out if paranormal activities are to blame.', 44, '2011-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 7, 'Cops & Robbers', 'A crew of bank robbers disguised as classic television doctors take hostages which include Castle and Martha. But things are complicated by the fact that Beckett''s on the outside having her every move scrutinized by a hostage negotiator and Castle''s on the inside with information that the hostages are just a distraction for a more ominous plan.', 44, '2011-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 8, 'Heartbreak Hotel', 'During the investigation of the murder of an Atlantic City casino owner at an abandoned warehouse, strong leads emerge for the team in both New York and Atlantic City. As Beckett and Capt. Gates work the New York leads together, Castle naturally chooses to join the detectives for the road trip to "America''s Playground," hoping to help solve the case while throwing an impromptu bachelor party for Ryan.', 44, '2011-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 9, 'Kill Shot', 'A sniper on a killing spree is terrorizing New York City. With the clock ticking down to the next murder and nothing to go on except a killer with no apparent motive but to instill terror, this could prove the team''s toughest case yet. The hunt is made even more complicated when Beckett begins to experience increasingly strong moments of PTSD - moments she tries hard to hide from Castle and the detectives.', 44, '2011-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 10, 'Cuffed', 'When Castle and Beckett wake up in bed, handcuffed together, in a locked room with no memory of how they got there, they must piece together the mystery of where they are and why, all while trying to escape. But as the two of them adjust to being shackled together, what''s the biggest threat they face... the people who abducted them or each other? Meanwhile, Ryan, Esposito and Gates are left to investigate their disappearance in a case where all is not what it seems.', 44, '2011-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 11, 'Till Death Do Us Part', 'When a lothario is killed, Castle and Beckett suspect that the victim’s mysterious double life holds the key to his murder. Their investigation leads to a shocking twist that threatens to disrupt Ryan’s wedding with Jenny', 44, '2012-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 12, 'Dial M for Mayor', 'It was longtime Castle friend Mayor Weldon''s political clout that allowed Castle to partner up with Beckett. But now, when a woman is found dead in a car that traces back to the Mayor''s motor pool, that partnership comes under fire as the scandal surrounding the investigation threatens to bring down Weldon''s administration.', 44, '2012-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 13, 'An Embarrassment of Bitches', 'When a famous dog trainer is killed, the investigation keeps coming back to charismatic reality TV star Kay Cappuccio. Kay, a favorite of tabloids and gossip websites the world over, has achieved stardom without possessing any discernible skill or talent. But there seems to be more to her story than she is letting on -- does that include murder?', 44, '2012-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 14, 'The Blue Butterfly', 'When Castle and Beckett investigate the killing of a treasure hunter, they discover the case is linked to a mysterious homicide from 1947 involving a hard-boiled private detective. Castle realizes the only way to solve the present-day murder is to solve the murder from the past. The 1947 case comes to life through stylized flashbacks, featuring Castle as the private eye and Beckett as a femme fatale.', 44, '2012-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 15, 'Pandora (1)', 'Castle and Beckett pursue a ruthless killer who, they discover, is part of a sinister, international conspiracy. Castle and Beckett are joined on the case by Sophia Conrad, a smart, sexy CIA operative who has a complicated past with Castle.', 43, '2012-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 16, 'Linchpin (2)', 'Castle & Beckett race to find the "Linchpin" in order to stop the first domino in a chain of events which will plunge the United States into war. Their efforts continue to put Castle in contact with Sophia Conrad - a smart, commanding and sexy CIA operative who was Castle''s inspiration for Clara Strike in the "Derrick Storm" series of books; and intelligence officer Martin Danberg is back.', 44, '2012-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 17, 'Once Upon a Crime', 'When a woman dressed as Red Riding Hood is found dead in the woods with claw marks covering her body, and soon after a murdered Snow White is discovered with a poison apple in her hand, Castle & Beckett find themselves on a Grimm hunt to catch a fairytale killer before he kills again. But nothing is as it seems in a case filled with deceit, betrayal, secrets and murder', 44, '2012-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 18, 'A Dance with Death', 'When Odette Morton, a contestant on the hit competition show “A Night Of Dance,” is found murdered in her dressing room, Castle and Beckett must navigate the case’s many twists and twirls without stepping on each other’s toes. But as they delve into Odette’s past, they discover that this reality starlet was harboring a shocking secret that may have led to her death', 44, '2012-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 19, '47 Seconds', 'When a bomb explodes at a protest rally killing five people, Castle and Beckett realize the key to solving the case is to reconstruct the 47 seconds prior to the explosion. Using video and witness accounts, they uncover the shocking truth about who planted the bomb.', 44, '2012-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 20, 'The Limey', 'A devilishly handsome detective from Scotland Yard, Simon Hunt, teams up with Castle & Beckett to find the person responsible for the murder of his friend''s daughter. Also, Nigel Wyndham, the Deputy General at the British Consulate whom Castle & Beckett suspect is up to more than just ambassadorial balls and diplomatic luncheons. Meanwhile, Lanie convinces Beckett that she needs to make a move on Castle before it is too late.', 44, '2012-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 21, 'Headhunters', 'With tensions rising between Castle and Beckett, Castle finds himself a new partner -- Detective Ethan Slaughter (guest star Adam Baldwin, "Firefly"), a tough and colorful cop from the city''s gang unit. But Castle gets more than he bargained for when Slaughter shows him a grittier side of police work that puts Castle in the line of fire like never before', 44, '2012-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 22, 'Undead Again', 'When Castle and Beckett investigate the murder of a man with human bite marks on his body, Castle''s wild theories start flying. But none are as wild as what their only witness insists happened - a Zombie attack. As the evidence pointing towards an undead assailant piles up, the team plunges into New York''s Zombie subculture to find the killer and bring him in -- dead, undead or alive', 44, '2012-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 4), 23, 'Always', 'When the murder of an Army veteran puts Beckett on the trail of the man who shot her, Castle must decide how much he''s willing to sacrifice to keep her safe. As secrets are revealed and feelings are put on the table, the lives of the detectives at the 12th Precinct may never be the same.', 44, '2012-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 5, 'Season 5', 'Now that Castle and Beckett have finally given in to their true feelings for each other, how will it affect their work together? As they try to keep their new relationship under wraps from their co-workers, the unlikely duo must track down the murderer of Beckett''s mother, find the perpetrator of a major conspiracy and untangle a line of investigation that links Castle to a ritualistic killing.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 1, 'After the Storm', 'Picking up the morning after, Castle and Beckett now have to decide if they''re a couple or was it just a onetime deal. But before they can tackle that, they must deal with those responsible for Kate''s mother''s death who are now a threat to Beckett.', 44, '2012-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 2, 'Cloudy with a Chance of Murder', 'On Beckett''s first day back from her suspension, she and Castle are thrown into the salacious world of local TV news when WHNY''s veteran weather girl is found dead. As if navigating an industry full of backstabbing and ruthless ambition weren''t difficult enough, they have to do it while hiding their new relationship from their coworkers', 43, '2012-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 3, 'Secret''s Safe with Me', 'A repossessed storage unit, treasure seekers and Manhattan socialites all come together in the case of a woman inexplicably murdered. Castle decides to enter the storage unit auction to see if anything inside might have led to her killing.', 44, '2012-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 4, 'Murder, He Wrote', 'Castle and Beckett’s plans for a romantic weekend in the Hamptons are interrupted when a dying man stumbles into Castle’s backyard, collapsing into his pool. Unable to escape the lure of the investigation they join up with the small town’s well-intentioned, but inexperienced sheriff to find the killer,', 44, '2012-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 5, 'Probable Cause', 'While investigating a shocking ritualistic murder, Beckett and her team uncover surprising evidence linking Castle to the killing. As the evidence against him mounts, loyalties are tested. And when surprising revelations come to light, Beckett begins to wonder how well she really knows her new lover and partner of four years', 44, '2012-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 6, 'The Final Frontier', 'When a body is found at a sci-fi convention, Castle and Beckett are warped into the heart of fandom -- a world of egotistic celebrities, diehard costumed fans and enough drama for two galaxies.', 44, '2012-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 7, 'Swan Song', 'A documentary crew follows Castle, Beckett and the team as they investigate the murder of a rock band''s lead guitarist.', 44, '2012-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 8, 'After Hours', 'In the aftermath of a disastrous "Meet the Parents" dinner, a bickering Castle and Beckett are sent to retrieve the only witness to a murder, but they get ambushed and are forced to take the witness on the run. Stranded in the middle of the night in a bad part of town, with no phone, badge or gun, Castle and Beckett must find a way to protect him from a team of mobsters -- that is, if they don''t kill each other first.', 44, '2012-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 9, 'Secret Santa', 'Castle and Beckett investigate when a bearded man named Kris Kringle falls from the sky in Central Park; Beckett and Castle work on a Christmas list together.', 44, '2012-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 10, 'Significant Others', 'When a powerful divorce attorney who only represented women is murdered, Castle and Beckett are confronted with a plethora of angry ex-husbands, any one of whom could be the murderer. Meanwhile, Castle''s ex-wife (Darby Stanchfield), Meredith, moves into the loft to take care of Alexis while she recovers from Mono, and to make matters worse, Beckett is also forced to move in while her apartment is being fumigated, causing tension, humor and more than a little awkwardness', 44, '2013-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 11, 'Under the Influence', 'When an up and coming DJ is killed at a pop star''s album release party, Beckett and Castle must dive into the raucous world of New York''s music industry. Then, when the investigation leads to a troubled teenager, Esposito takes the kid under his wing, hoping to put him on the right track before it''s too late.', 44, '2013-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 12, 'Death Gone Crazy', 'When Beau Randolf, the founder of hit adult video franchise "College Girls Gone Crazy," is murdered, Castle and Beckett are confronted with a lengthy list of husbands, fathers and ex-college girls who all have motive. So to find the killer, they must delve deep into the victim’s life, where they find surprises at every turn. Also Alexis starts a video blog, but Castle is not happy that personal and intimate details about her life are being made public.', 41, '2013-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 13, 'Recoil', 'While investigating the murder of a young woman, Castle and Beckett find evidence that links her death with Senator William H. Bracken (Jack Coleman), the man responsible for Beckett''s mother''s murder. Determined to finally bring Bracken to justice, Beckett soon realizes that things are far more complicated than they seem.', 44, '2013-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 14, 'Reality Star Struck', 'Castle & Beckett get an up-close-and-personal view of a "Real Housewives"-esque reality TV series, "The Wives of Wall Street," when they investigate the murder of the show''s rising young star. Meanwhile, Castle''s attempt to give Beckett a Valentine''s Day gift goes horribly wrong.', 44, '2013-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 15, 'Target (1)', 'In the first of a two-episode story arc, Castle and Beckett begin a murder investigation that also exposes a plot to kidnap the daughter of a wealthy Middle Eastern businessman. FBI Agent Harris, an even-keeled professional is brought in to help find the kidnappers.', 44, '2013-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 16, 'Hunt (2)', 'In the powerful conclusion of a two-episode story arc, when the FBI fails to get his daughter back, Castle takes matters into his own hands, reaching out to a shadowy fixer to help him recover Alexis. But Castle soon learns that his daughter''s kidnapping may be part of an even more sinister agenda.', 44, '2013-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 17, 'Scared to Death', 'When a young woman appears to have literally been scared to death three days after watching a "haunted" DVD, Castle and Beckett delve into one of their creepiest cases yet. To make matters worse, Castle becomes convinced that he too is marked for death when he accidentally watches the cursed video.', 44, '2013-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 18, 'The Wild Rover', 'When a man is found dead in an industrial cake mixer, Castle and Beckett trace the murder to an Irish gang in Staten Island and a beautiful bar owner named Siobhan O’Doul. Much to everyone’s surprise, Detective Ryan has a complicated history with Siobhan and the Staten Island crime family from his days working undercover in narcotics. When the case hits a dead end, Ryan must go back undercover to expose the killer, complicating his relationship with his wife.', 44, '2013-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 19, 'The Lives of Others', 'In the show’s 100th episode, Castle finds himself in the unfortunate position of NOT being able to work a case. While he’s holed up in the loft with a broken leg, Beckett goes off to investigate the death of an IRS agent without him, leaving Castle miserable and bored. But when he thinks he witnesses the murder of a young woman in the apartment across the street, he is thrown into a "Rear Window"-esque murder mystery that hits much too close to home.', 44, '2013-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 20, 'The Fast and the Furriest', 'When Castle and Beckett find giant footprints at the site of a vicious murder, the team is forced to confront the unlikely theory that Bigfoot is the killer. But as they trek into the world of primate research, big game hunting and mythological creatures, they realize that finding the man (or beast) responsible may put them on the endangered species list.', 44, '2013-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 21, 'The Squab and the Quail', 'When Beckett is assigned to protect Erik Vaughn, a charming billionaire entrepreneur whose life is in danger, she''s forced to reflect on her relationship with Castle which has begun to plateau. Meanwhile, consumed with jealousy, Castle goes to extraordinary lengths to solve the case and separate the two of them.', 43, '2013-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 22, 'Still', 'Beckett''s life is on the line when she steps on a pressure sensitive bomb. While the team searches for a way to disarm the explosive, Castle distracts Beckett by arguing with her about who fell for whom first.', 44, '2013-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 23, 'The Human Factor', 'When Homeland Security inexplicably seals the crime scene of a car bombing, Castle and Beckett find themselves with two mysteries on their hands: who murdered the victim, a government whistleblower, and why are federal agents trying to take over the case? The plot thickens when they discover that the victim wasn''t killed by a car bomb but by a missile from a military drone.', 44, '2013-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 5), 24, 'Watershed', 'In the season finale, an interview with a high-profile federal law enforcement agency forces Beckett to reconsider what she wants out of her job and out of her relationship with Castle. Meanwhile, the body of a young woman is found floating inside the water tank of a skid row flop house, but as the team investigate, they discover that her final resting place is just one of many strange things about her death.', 44, '2013-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 6, 'Season 6', 'After Castle''s stunning romantic proposal to Beckett, what happens next? The magnetic crime-fighting couple faces a whole new set of challenges as they juggle wedding plans and their most intriguing cases yet.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 1, 'Valkyrie (1)', 'Last season ended with Beckett wrestling over whether to take a high-profile job in DC -- a dilemma made more complicated when Castle proposed to her. In the Season 6 Premiere of "Castle," Castle and Beckett will deal with the consequences of their decisions against the backdrop of a high-stakes investigation.', 44, '2013-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 2, 'Dreamworld (2)', 'Continuing from the season premiere episode, Beckett races against time to find a stolen toxin capable of killing tens of thousands of people. To make matters worse, Castle was exposed, leaving him with less than 24 hours to live.', 43, '2013-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 3, 'Need to Know', 'With Beckett still in D.C., Castle and the boys investigate the murder of former child star Charlie Reynolds, who rose to fame playing the lovable nerd on an early 90s High School sitcom. But the case takes a turn for the strange when Agents Beckett and McCord arrive from Washington to take over the investigation, creating competitive tension in the precinct. But why would a washed-up actor''s death warrant Federal scrutiny? Whatever the reason, Beckett and McCord aren''t telling. Meanwhile, Castle has to contend with a new face at the 12th, NYPD Detective Frank "Sully" Sullivan.', 44, '2013-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 4, 'Number One Fan', 'A desperate young murder suspect, Emma Briggs, takes hostages at gunpoint then mysteriously insists that she will only negotiate with one person: Richard Castle.', 44, '2013-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 5, 'Time Will Tell', 'A grisly murder investigation leads Castle and Beckett to a suspect who claims he''s traveled back in time to stop terrible events from unfolding, events that will change the course of human history. Is he simply a deluded killer, or is it possible that he''s telling the truth?', 44, '2013-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 6, 'Get a Clue', 'As Castle and Beckett investigate the ritualistic murder of a young woman, they find strange symbols in the victim''s apartment; Castle struggles with Alexis'' decision to move in with Pi.', 44, '2013-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 7, 'Like Father, Like Daughter', 'Alexis enlists Castle’s help on an Innocence Review case to prove that a death row inmate, Frank Henson, was wrongly convicted. With only 72 hours left before his execution, Castle and Alexis (with help from Beckett) urgently investigate the original murder, only to uncover explosive secrets that may seal Frank’s fate.', 44, '2013-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 8, 'A Murder Is Forever', 'When a famed relationship therapist is murdered, it appears that her access to the secrets of her elite and powerful clients led to her death. But when Castle and Beckett discover the victim was in possession of a rare object worth millions of dollars, they realize that this case may be even more complicated – and dangerous – than they thought.', 44, '2013-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 9, 'Disciple', 'Castle and Beckett arrive at a crime scene to discover that the female victim bears a shocking resemblance to Medical Examiner Lanie Parish. As the team tries to make sense of this mystery, they realize the killer may be targeting detectives of the 12th Precinct. Dr. Kelly Nieman, an exclusive Manhattan cosmetic surgeon who draws Castle and Beckett''s interest because of her connection to the victim.', 44, '2013-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 10, 'The Good, The Bad & The Baby', 'Before dying, he hands a mysterious bundle to the priest. When the bundle turns out to be a smiling baby boy, Castle and Beckett find themselves accidental nannies to the newborn. But when they determine the baby and the victim were not related, they discover that finding his rightful parents may be just as hard as solving the murder.', 44, '2013-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 11, 'Under Fire', 'When Castle and Beckett discover that the victim of a building fire was actually shot to death, they get on the trail of a serial arsonist turned murderer. Meanwhile, Ryan''s wife, Jenny, goes into labor, but disaster threatens to ruin the joyous moment.', 44, '2014-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 12, 'Deep Cover', 'The murder of a young record store clerk takes a strange turn when the team discovers his past history as a high-level hacker. But it''s nothing compared to the shock Castle receives when their investigation leads them straight to his father, Jackson Hunt.', 44, '2014-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 13, 'Limelight', 'When a pop star is found dead in an alley, Beckett and Castle look into her hard-partying lifestyle; a shocking revelation rocks the investigation.', 44, '2014-01-20');
