INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 15, 'Smells Like Teen Spirit', 'The murder of a high school mean girl draws Castle back to one of his many alma maters, where he is giddy to learn that the evidence points to a surprising perpetrator - a teenage telekinetic, throwing he and Beckett into a real-life "Carrie."', 44, '2014-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 16, 'Room 147', 'When a guilt-ridden young woman confesses to the murder of a struggling actor -- knowing details only the killer could know -- Beckett and Castle seem to have an open-and-shut case, until they uncover proof that their suspect couldn’t possibly be the killer. When a second person confesses, equally convinced they committed the murder, the team realizes the case is far more mysterious than they thought.', 44, '2014-02-24');
