INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 18, 'The Way of the Ninja', 'When a Japanese ballet dancer is mysteriously murdered, Castle and Beckett''s investigation into her secret life uncovers evidence that she was killed by a ninja, and now that ninja is coming after them.', 44, '2014-03-17');
