INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 20, 'That ''70s Show', 'When construction workers find the body of an infamous New York mobster who disappeared in the seventies, Beckett and Castle try to solve this three decade-old mob hit. Unfortunately, their only witness is a man who thinks it’s still the 1970’s, so to uncover what he knows, they must play into his delusion, and party like it’s the last days of disco.', 44, '2014-04-21');
