INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 22, 'Veritas', 'A secret investigation conducted by Beckett related to her mother''s murder goes awry when a man she has been surveilling is killed. When evidence links Beckett to the victim, she and Castle become the targets of a manhunt that puts both of them in grave danger.', 44, '2014-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 6), 23, 'For Better or Worse', 'Castle and Beckett''s long-awaited wedding is almost here, but when a shocking surprise threatens to ruin the big day, they are sent on a wild mission filled with masked men, angry bikers and a charming ne''er-do-well from Beckett''s past.', 44, '2014-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 7, 'Season 7', 'The wedding bells are ringing, but will Castle and Beckett really tie the knot? On the biggest day of his life, Castle is nowhere to be found, and it''s not because he has cold feet. Now, in a season of brilliant twists and turns, Castle and Beckett take on New York City''s most fascinating cases while they try to solve the mystery of their own relationship.');
