INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 7), 21, 'In Plane Sight', 'As Castle and Alexis travel to London, their routine flight turns deadly when the plane’s Air Marshal is found murdered. With the help of Beckett on the ground, Castle and Alexis race against time to find the killer before he carries out his fateful plan.', 44, '2015-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 7), 22, 'Dead From New York', 'When Sid Ross, the powerful creator of a long-running sketch comedy show is killed, Castle and Beckett are called to investigate. But as they delve into the victim’s life and the colorful world of “Saturday Night Tonight,” they uncover a shocking secret that may explain Sid’s murder.', 43, '2015-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 7), 23, 'Hollander''s Woods', 'A death in the woods draws Castle back to a terrifying and defining event in his childhood. Investigation leads to obsession, as he attempts to unearth answers that have eluded him for decades, all while Beckett faces a crossroads of her own.', 44, '2015-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')), 8, 'Season 8', 'In the Season 7 finale, Beckett was faced with a choice about her future.  Now that she''s been promoted to Captain, how will New York''s famous  couple adapt in Season 8?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 1, 'XY (1)', 'After passing the Captain''s exam last season, Beckett was surprised with an offer to run for State Senate. In the action packed season premiere, Castle and Beckett are adjusting to Beckett''s career change, when a call from a mysterious stranger sets off an explosive chain of events. There are two sides to every story, and this unique two-parter will explore the same story from each of their perspectives, first from Castle''s side as he searches for Beckett.', 44, '2015-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 2, 'XX (2)', 'Beckett''s side of her abrupt disappearance is revealed. After receiving a mysterious tip from her past, Beckett is launched into a fight for her life, with a team of mercenaries hot on her trail. While Castle investigates why his wife is on the run, Beckett must figure out who wants her dead, before they can finish the job.', 44, '2015-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 3, 'PhDead', 'When the body of a local college fraternity student is found gruesomely murdered, Castle has to go undercover as a professor in order to gain access to the victim''s world. However, he and Beckett soon discover that behind the fun and games of college are some darker secrets the university wants to keep hidden.', 44, '2015-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 4, 'What Lies Beneath', 'When Castle''s idol, a famously reclusive author, turns up dead, Castle is determined to solve his hero''s murder. But as he and Beckett dig deeper, they discover that truth is stranger than fiction.', 44, '2015-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 5, 'The Nose', 'When a priceless work of art is stolen and its transporter murdered, Castle and Beckett must work with the key witness to track down the painting and sniff out the killer.', 44, '2015-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 6, 'Cool Boys', 'Detective Slaughter returns to enlist Castle’s help in solving a high-stakes robbery case. But when a body is found linked to the crime, Slaughter becomes the number one suspect in the heist turned murder, while Castle has to determine whether he’s guilty or help to prove he’s innocent.', 44, '2015-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 7, 'The Last Seduction', 'In order to hunt down the brutal murderer of a grifting seducer, Castle & Beckett must investigate New York’s elite. Meanwhile, Castle plans to surprise Beckett on their one-year wedding anniversary.', 44, '2015-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 8, 'Mr. & Mrs. Castle', 'Castle and Beckett investigate the murder of a cruise ship entertainer, only to find themselves trapped at sea with the killer.', 43, '2015-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 9, 'Tone Death', 'When a body is found in the theater of Martha’s latest show, Castle and Beckett’s investigation leads them into the unexpectedly dangerous world of competitive a capella.', 44, '2016-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 10, 'Witness for the Prosecution', 'Castle finally gets his day in court when he takes the stand as the key witness to a murder from five months ago. But when new information suddenly arises, he and Beckett must race against the clock to prevent a miscarriage of justice.', 44, '2016-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 11, 'Dead Red', 'When the son of a Russian diplomat turns up murdered, Beckett and Castle find themselves in a dangerous game of international crime and punishment, with Castle having to entertain a jovial Russian security officer who winds up more involved than anyone planned.', 44, '2016-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 12, 'The Blame Game', 'Castle is captured and forced to work with strangers to solve deranged puzzles and mind games, while Beckett and the 12th Precinct must race against time to rescue Castle and catch a killer.', 44, '2016-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 13, 'And Justice for All', 'Beckett and the 12th Precinct look into the murder of an English as a Second Language student. But when the victim''s class won''t talk to the police, Castle goes undercover as a French Canadian immigrant and learns that the victim was more than he seemed.', 44, '2016-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 14, 'The G.D.S.', 'Castle returns to the City of Angels in search of answers about his missing time. But things take a deadly turn when he’s recruited by the legendary Greatest Detective Society to help solve a murder.', 44, '2016-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 15, 'Fidelis Ad Mortem', 'When a recruit officer at the NYPD Academy is killed, Beckett and the team go back to their old training ground to investigate. Meanwhile, Castle must reckon with a decision with profound consequences for him and Beckett.', 44, '2016-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 16, 'Heartbreaker', 'A clue at the scene of the death of an armored-car driver leads Beckett and Castle back to an old case solved by Esposito. But complications arise when they learn that Esposito might not have been telling them everything about his past with the culprit.', 44, '2016-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 17, 'Death Wish', 'The murder of a man connected to smuggling Turkish relics sends Castle, Beckett and the 12th Precinct on a search for a stolen antique believed to be Aladdin’s lamp, in hopes that it can lead them to the killer.', 43, '2016-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 18, 'Backstabber', 'After Hayley does a favor for an old friend, she finds herself implicated in a killing and cyber-terror attack. Now, Beckett and Castle must rush to solve the case and clear Hayley’s name.', 44, '2016-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 19, 'Dead Again', 'When a mild mannered safety inspector for the city miraculously survives a poisoning, it might be luck; but when he survives another, it’s a mystery Castle and Beckett will have to solve.', 44, '2016-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 20, 'Much Ado About Murder', 'After a movie star turned theater actor is mysteriously killed, Castle and Beckett go backstage and learn the star had more to worry about than just his lines.', 44, '2016-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 21, 'Hell to Pay', 'When an axe-wielding, escaped psychiatric inmate drops dead in Castle’s P.I. office, Castle and Beckett’s investigation leads Castle to suspect the victim’s death could be the work of the Antichrist.', 44, '2016-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1219024')) AND numero_temporada = 8), 22, 'Crossfire', 'With their best lead in hand, Castle and Beckett are ready to take on LokSat. But an unforeseen twist puts their case – and their lives – in jeopardy.', 44, '2016-05-16');
