INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1232200', 'That''s My Boy', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1890845'), 'PELICULA', 'While in his teens, Donny fathered a son, Todd, and raised him as a single parent until Todd''s 18th birthday. Now Donny resurfaces just before Todd''s wedding after years apart, sending the groom-to-be''s world crashing down.', '2012-01-01', 'https://m.media-amazon.com/images/M/MV5BMTM3NDMyNzgzMV5BMl5BanBnXkFtZTcwMjIyMTA1Nw@@._V1_.jpg');
