INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')), 1, 'Season 1', 'The first season of the new 90210 looks at life through the eyes of Annie Wilson and her brother Dixon, whose first day at West Beverly Hills High School leaves no doubt they’re not in Kansas anymore. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 1, 'We''re Not in Kansas Anymore', 'In part one of the series premiere, Harrison Wilson accepts the job position as principal of West Beverly Hills High,  forcing the Wilson family to relocate from Kansas to California and adjust to new life in the city - all while keeping a close watch on their troubled grandmother Tabitha.', 44, '2008-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 2, 'The Jet Set', 'In part two of the series premiere, Dixon must deal with jealous teammates on the lacrosse team and Annie is dumped by her boyfriend back home but soon meets a potential love interest.', 40, '2008-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 3, 'Lucky Strike', 'Harry and Debbie plan a family bowling night, but find their plans interrupted by the unexpected arrival of Annie and Dixon''s friends. Meanwhile, Annie finds herself torn between Ethan and Ty, Naomi experiences a difficult evening with her father, and Kelly and Silver learn that Jackie''s drinking is beginning to spiral out of control.', 40, '2008-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 4, 'The Bubble', 'Annie, Harry, and Debbie are surprised to find out that West Beverly''s theater director can''t direct the school musical anymore. Kelly persuades Brenda to take over as the play''s director, but they end up arguing over Kelly''s involvement with Ryan. Meanwhile, Dixon tries to get a part-time job at the Peach Pit and Naomi confronts her father''s mistress.', 40, '2008-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 5, 'Wide Awake and Dreaming', 'As the opening night of the school play "Spring Awakening" approaches, Ty reveals to Annie his plans for a one-on-one after-party in his hotel room with her. Others at school are concerned about how fast Annie and Ty''s relationship is developing. Meanwhile, Naomi won''t accept her parents'' divorce and Adrianna is confronted about a substance abuse problem, which gives Annie a chance to be the lead in the play.', 40, '2008-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 6, 'Model Behavior', 'When Debbie is given the opportunity to shoot a fashion show for Nylon Magazine, Annie uses the event for a school project. Naomi tries to use the shoot to mend her parents'' marriage, but her plan ends up backfiring. Meanwhile, Kelly receives a phone call that changes her relationship with Ryan.', 40, '2008-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 7, 'Hollywood Forever', 'Annie and Ethan get paired up for a class project where they must take care of a baby. This time together forces them to see each other in a new light. At Silver''s half-birthday party, Silver and Dixon continue to get closer. Meanwhile, Harry and Debbie must deal with Harry''s past when Tracy tells Harry that she''s hired an investigator to find their son. Elsewhere, Ryan tries to cope with Kelly leaving and decides to try online dating.', 40, '2008-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 8, 'There''s No Place Like Homecoming', 'After recuperating from her health scare, Adrianna returns and tries to make amends with Naomi, but her ex-BFF refuses to forgive her for the betrayal. Adrianna makes a surprising connection with Navid, who helps her through her situation. Meanwhile, Annie and Ethan finally take their rapidly growing romance to a new level during the school''s homecoming dance, causing Naomi to feel jealous.', 40, '2008-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 9, 'Secrets and Lies', 'Harry and Debbie reveal to Annie and Dixon that Harry had a son who was given up for adoption 22 years ago. Meanwhile, Silver has the girls over for a girls'' night, but the simple night together quickly escalates into a house party.', 40, '2008-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 10, 'Games People Play', 'Noami grows spiteful as Annie and Ethan grow closer, causing her to deliver an unwelcomed surprise at Annie''s sweet 16 party. Meanwhile, the school is all buzzing over the news that Ryan was given a leave of absence, and Adrianna discovers Navid''s secret.', 40, '2008-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 11, 'That Which We Destroy', 'Brenda and Kelly''s friendship takes a turn for the worse. Meanwhile, Sean moves in with the Wilson family, Naomi hangs with a new crowd, and Silver becomes jealous when a cheerleader pays a little too much attention to Dixon', 40, '2008-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 12, 'Hello, Goodbye, Amen', 'Brenda receives life changing news. Meanwhile, Dixon grows closer to Christina, and an unexpected secret is destined to rock Adrianna''s world.', 40, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 13, 'Love Me or Leave Me', 'Debbie and Tabitha clash after Tabitha surprises Annie and Dixon with a new car. Adrianna begins to open up to Naomi about her secret. Meanwhile, Silver and Dixon spend the day together at the beach, but things take an awkward turn when Dixon says three little words.', 40, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 14, 'By Accident', 'Adrianna must cope with her decision about her baby and her baby''s father and turns to Naomi and Kelly for support. Ethan helps Annie prepare for the school play''s try-out and are shocked to find out that Ty is also auditioning. Meanwhile, Dixon asks Debbie for relationship advice.', 40, '2009-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 15, 'Help Me, Rhonda', 'Adrianna tells the baby''s father and her mother that she is pregnant. Meanwhile, Annie feels threatened by Ethan''s friendship with Rhonda; and Silver finally opens up to Dixon.', 40, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 16, 'Of Heartbreaks and Hotels', 'Naomi meets an intriguing mystery man at her new home; Silver''s Valentine''s Day surprise falls apart, but she and Dixon still manage to come together. Meanwhile, Annie''s jealousy of Rhonda starts to wear on Ethan.', 40, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 17, 'Life''s A Drag', 'Liam displays his dark side to Naomi, who is stunned but captivated by the intense, handsome bad-boy. Meanwhile, Annie and Ethan face another bump in their relationship when Adrianna makes it known that Ethan and Rhonda shared a kiss, and Silver and Dixon make a video that stirs quite a controversy at West Beverly Hills High.', 40, '2009-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 18, 'Off the Rails', 'When Dixon tries to slow down the pace of their relationship, Silver takes a trip to Kansas to learn what he was like before coming to Beverly Hills. Unfortunately, her fragile mental state gets her involved in a difficult situation. Meanwhile, Kelly once again faces her troubled mother Jackie.', 40, '2009-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 19, 'Okaeri, Donna!', 'Kelly and Silver are shocked when Donna arrives in town. Annie and Dixon take a road trip to visit someone from Dixon''s past while Ethan spends his spring break working for Habitat for Humanity. Naomi also decides to work for Habitat when she learns that Liam will be there.', 40, '2009-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 20, 'Between a Sign and a Hard Place', 'Now that they have finally sold their home in Kansas, Harry and Debbie have a yard sale, Beverly Hills-style. Meanwhile, Donna talks to Kelly about her separation, and later search for a place for Donna to open a clothing store; Dixon helps Silver in her recovery; Liam and Ethan''s unlikely friendship continues; and when a scandal involving Naomi''s father comes to light, her trust in Annie begins to falter.', 40, '2009-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 21, 'The Dionysian Debacle', 'Naomi''s older sister, Jen, unexpectedly returns to Beverly Hills. Meanwhile, Naomi persuades Annie to go on a double date, and Adrianna and Navid reveal their decision to his parents.', 40, '2009-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 22, 'The Party''s Over', 'Following their engagement, Navid and Adrianna celebrate their respective bachelor and bachelorette parties. While Adrianna feasts with friends and family at the Wilson home, Navid and the boys spend a wild night with college girls at a burlesque club. Meanwhile, sparks fly between Ryan and Jen, and Dixon continues to feel unappreciated by Silver.', 40, '2009-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 23, 'Zero Tolerance', 'With prom night quickly approaching, Annie, Adrianna, Naomi, and Silver get glammed up by a famous stylist. A dateless Annie agrees to attend the event with the extremely nerdy Charlie, who is massively crushing on the popular girl. But when he realizes that her interest is purely platonic, a furious Charlie plots an evil revenge. Meanwhile, Dixon is nominated for Prom King, Ethan gets accepted into lacrosse camp, and Kelly and Harry work to get Liam on the right track.', 40, '2009-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 1), 24, 'One Party Can Ruin Your Whole Summer', 'Adrianna and Navid are forced to make an impromptu exit from the prom when Adrianna goes into labor. Dixon confronts Ethan about Silver when he notices that Ethan might be developing feelings for his girlfriend. Meanwhile, Annie reaches the breaking point when Naomi accuses her of trying to hook up with Liam, and some of her peers (still angry about the after party fiasco) decide to take both verbal and physical action against her.', 40, '2009-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')), 2, 'Season 2', 'The second season focuses on the West Beverly Hills High group as they go through dramatic changes and surprises that will change their lives. Annie Wilson must deal with the consequences of the hit and run when she finds out the man''s nephew goes to West Bev. Meanwhile, Naomi''s sister, Jen Clark continues to manipulate and use her for whatever she can; Dixon finds a new girlfriend; Silver and Kelly Taylor must come to terms with devastating news; Adrianna begins a journey of independent and personal growth. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 1, 'To New Beginnings!', 'Forced to attend summer school following the police crashing Naomi''s after-prom party, Naomi, Silver and Adrianna form a tight bond with one another, while Annie finds herself more isolated from her friends and family as she worries about her hit-and-run. As summer draws to a close, the gang hangs out at the Beverly Hills Beach Club, where Naomi and Silver meet Teddy, the son of a famous movie star. Meanwhile, Dixon and Silver work to save their relationship, but it may be too little too late.', 40, '2009-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 2, 'To Sext or Not to Sext', 'Naomi is still furious with Annie from prom night and contemplates sending out a sexually explicit text message of Annie as payback. Silver is convinced that she and Dixon can mend their broken relationship, but Naomi and Adrianna convince her to give him some much-needed space. Liam attempts to apologize to Naomi for what happened on prom night and denies sleeping with Annie, but refuses to reveal who he was with. Meanwhile, Liam and Dixon join the surf team, in an effort to keep Liam''s stepfather from sending him off to military school. Adrianna helps Navid, now in charge of The Blaze News, land an interview with Teddy, but she is shocked with Navid''s interviewing tactics. Ryan continues to pursue Jen , who continues to play hard-to-get.', 40, '2009-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 3, 'Sit Down, You''re Rocking the Boat', 'Annie is humiliated that the entire school received her sext message and is on a mission to reveal Naomi as the sender of the revealing photo. Harry and Debbie attempt to discuss Annie''s situation but the conversation only causes more tension, leading Harry to open up to Kelly about his family problems. Dixon meets his dream girl, Sasha and sparks immediately begin to fly, though he fails to reveal his true age. Silver continues to get over Dixon while Adrianna and Navid deal with Teddy''s presence in their life. Liam, fed up with the lies between Naomi and Annie, retreats to his garage to work on a mysterious project. The gang joins Teddy on his father’s yacht for an afternoon of ocean-filled drama', 40, '2009-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 4, 'The Porn King', 'Dixon and Sasha continue their whirlwind romance by driving to Napa for the weekend, but on the return trip a flat tire leads to a trunk of porn and a bunch of lies. Annie''s confident attitude quickly disappears when she realizes that Jasper, the nephew of the man she hit on prom night, is a student at West Beverly. Navid continues to run the Blaze News and assigns Silver and Gia to interview Jasper for a news piece about his uncle. Things get steamy when Adrianna confides in Teddy, resulting in Adrianna and Navid finally spending the night together. Liam finally finds a way to get revenge on Jen and reveal the truth to Naomi about their night together at prom.', 40, '2009-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 5, 'Environmental Hazards', 'Naomi learns that her test scores may not be high enough for her to be accepted into CU. Devastated, Naomi devises a plan to be tutored by Richard, the son of the school''s dean of admissions, but quickly realizes she would much rather be studying Jamie, a CU student. Dixon''s girlfriend, Sasha, becomes suspicious about his age and does a little detective work to learn the truth, leaving Dixon devastated. Navid and Adrianna double date with Teddy, but Adrianna’s growing feelings towards Teddy make for an awkward situation. Silver accompanies Adrianna to an AA meeting and surprisingly bumps into her mom, Jackie, who tells Silver she would like to re-establish their relationship. An angry Silver rejects her mother, but her world is turned upside down when Adrianna reveals shocking news about Jackie.', 40, '2009-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 6, 'Wild Alaskan Salmon', 'Kelly and Silver deal with the shocking news that their mother, Jackie, is dying of breast cancer. Kelly doesn’t want to be sucked back into her mother’s bad behavior, but Silver feels differently. Navid''s world is turned upside down when Adrianna reveals that she needs time alone, but turns to Teddy for attention. Jen continues to manipulate Naomi and manages to convince Naomi to lend her a large amount of cash. Jasper rescues Annie from a bad date and the two forge a bond that will be hard to break. Harry accompanies Ryan to a bar for some guy time and attempts to be his wing man.', 40, '2009-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 7, 'Unmasked', 'It''s Halloween at the Beverly Hills Beach Club and Adrianna channels Marilyn Monroe to help her deal with the end of her relationship with Navid. Silver and Kelly continue to have differing opinions about caring for Jackie. Silver is overloaded with school work and caring for her mom, but soon learns that she and Teddy have more in common than a class project. Naomi continues her relationship with Richard, but when she and Jamie share an intimate conversation, her plans to schmooze with the dean of CU come to a screeching halt. Dixon realizes he and Sasha are in two different places in their life and decides to end their relationship, but she ends up delivering life-changing news. Tensions rise between Debbie and Harry when she walks in on Harry and Kelly in his office. Annie and Jasper’s relationship is put to the test when he attempts to convince her to steal a car while shooting a scene for his student film. Liam butts heads with the newest member of the surf team, Ivy.', 40, '2009-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 8, 'Women''s Intuition', 'Navid and Gia launch an investigation into student drug use at West Beverly for Blaze News, which leads them to Annie''s boyfriend, Jasper leaving Annie torn over who to believe. Fresh off his break-up with Adrianna, Navid receives dating advice from Samantha Ronson while out with Liam, Teddy and Ivy at the Edison. Worried that Adrianna will relapse, Naomi and Silver enlist Navid''s assistance. Dixon reveals his situation with Sasha to Debbie and Harry, prompting Debbie to do some investigating. Jen and Ryan meet up with Pharrell to watch a performance of N.E.R.D.', 40, '2009-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 9, 'A Trip to the Moon', 'With the help of Teddy, Jackie surprises Silver with a half-birthday celebration that takes her back to her childhood birthday parties. Navid witnesses Adrianna buying drugs from Jasper, forcing Navid to confront him about being a drug dealer. Dixon is determined to confront Sasha about her miscarriage, forcing Debbie and Harry to reveal that Sasha lied about being pregnant. Annie and Jasper profess their love for each other and decide to take their relationship to the next level. After getting into a fight on the beach, Liam, with the help of Dixon, Teddy and Ivy, devises a plan seek revenge on Jen.', 40, '2009-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 10, 'To Thine Own Self Be True', 'Annie leaves Debbie and Harry surprised when she informs them that she would like to invite Jasper over for dinner. Dixon decides to pass on the event as a result of his anger over Debbie''s management of the Sasha situation. Meanwhile, Kelly shows support for Silver regarding the caring of Jackie despite the fact that she does not yet know if she can ultimately forgive her mother for all the pain she has caused in the past. Navid confronts Adrianna about her drug use, and a weekend camping trip leads to Ryan and Jen''s relationship climbing to a new level. Also, Naomi is caught kissing Jamie by Richard and his mother, forcing her to come clean about her plans for CU admission.', 40, '2009-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 11, 'And Away They Go!', 'Navid wakes up in the hospital but has no memory of who pushed him down the stairs. Adrianna visits Navid and following her conversation with him, makes a life-changing decision about her addiction to pills. Silver and Teddy bond over the loss of both of their mothers and unexpectedly get close. Liam, Dixon and Ivy learn that Naomi and Jen will be attending the horse races and devise a plan to finally reveal the truth to Naomi about her evil sister. Annie and Jasper sneak out even though Harry and Debbie have grounded her.', 40, '2009-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 12, 'Winter Wonderland', 'Navid is convinced Jasper pushed him down the stairs and turns to Adrianna to help reveal the information. Annie is confronted by her friends about Jasper''s drug dealing but when she confronts him about the news he reveals his suspicions about her involvement in the hit and run. Naomi and Silver decide to spend Christmas break in St. Barts but first make an appearance at the beach club for the winter dance. Teddy reveals his feelings for Silver, causing Dixon to be jealous, while Naomi and Liam attempt to forgive each other for what happened with Jen. Debbie attempts to spend some quality time with Dixon by taking him to the arcade.', 40, '2009-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 13, 'Rats and Heroes', 'Naomi returns from her vacation in St. Bart’s excited to spend time with Liam, which leads to the two getting up close and personal in his newly built boat. Adrianna and Gia bond during an AA meeting and establish a support system for each other which leads to the two sharing a kiss at the Beach Club. Navid and Dixon devise a plan to eliminate Jasper from Annie’s life, but never anticipate the outcome of a school drug search. Dixon attempts to rekindle his relationship with Silver, while Silver hides her true feelings for Teddy. Harry and Debbie run into Kelly while attending a school function and Debbie confronts Kelly about having a crush on Harry.', 40, '2010-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 14, 'Girl Fight', 'Naomi enlists Ivy’s help in reducing the awkwardness with Liam and the three decide to go on a hike, something Naomi has never done. Naomi discovers Ivy’s alterior motives and confronts her by pushing her face in the sand. Naomi, Silver and Adrianna go shopping in the Palisades and run into Annie and Jasper. Jasper blackmails Annie with photographic proof of her hit-and-run, but she gives Jasper an ultimatum that puts her mind at ease. Adrianna and Gia’s friendship continues to develop when the two throw a pity party for themselves. Silver and Teddy toy with the idea of trying to make a relationship work. Ryan meets free-spirited Laurel at a bar, but soon they move to her car so they can get to know each other even better. A surprise visitor shows up on the Wilson’s doorstep.', 40, '2010-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 15, 'What''s Past is Prologue', 'Gia encourages Adrianna to audition for a new band and admits she has a crush on Adrianna. Dixon''s birthmother, Dana drops by for a surprise visit and tries to develop a relationship with her son. Silver and Teddy go on their first official date but Silver finds it difficult to deal with Teddy''s playboy past and enlists Naomi''s help to track his whereabouts. Navid returns from his suspension to find that Naomi has started a gossip segment during Blaze News, which he adamantly opposes. Navid decides to get back into he dating scene by asking Lila out on a date, his first since breaking up with Adrianna. Annie realizes that Jasper has started following her around town. Debbie confides in Kai, her yoga instructor, about the arrival of Dixon''s birthmother.', 40, '2010-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 16, 'Clark Raving Mad', 'Naomi immediately butts heads with the Blaze''s new faculty advisor, Mr. Cannon, and is reprimanded in front of her peers. After failing to convince Navid to back her opinion, Naomi decides to tell a tiny lie that soon snowballs out of control. Adrianna is now the lead singer of the Glorious Steinems and confides in Silver and Naomi about her newfound feelings for Gia, and the two go out on their first official date. Teddy decides to test Silver by attempting to make her jealous. Dixon and his birthmother Dana continue to bond. Liam catches his stepfather with another woman and confronts him with his fist. Debbie and her instructor, Kai share tea and conversation after yoga, but Kai oversteps his boundaries.', 40, '2010-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 17, 'Sweaty Palms and Weak Knees', 'Annie deals with the outcome of Jasper’s decision to jump from the Hollywood sign and begins to find some peace with her situation. Silver and Teddy decide to double date with Liam and Naomi, which makes Dixon and Ivy feel left out, so the two decide to fake date. Adrianna and her band perform for the first time at the Beach Club and, with her newfound confidence, Adrianna decides to make her relationship with Gia official in a very public way. Liam encourages Naomi to come forward with her sexual harassment case, which causes her to continue her lie.', 40, '2010-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 18, 'Another Another Chance', 'Naomi’s little white lie has become the talk of the school, and when she is forced to testify in front of the school board, she drops a bomb that no one saw coming. Annie is finally able to put her relationship with Jasper behind her, but when she and Silver inadvertently drive past the scene of her hit-and-run, the guilt comes rushing back to haunt her. Dixon and Ivy’s fake-dating situation continues and the two make a decision that neither one anticipated. Adrianna and Navid share a friendly conversation which doesn’t go over well with their significant others, Gia and Lila. An argument between Gia and Adrianna results in Adrianna walking in on Gia and her ex-girlfriend. Liam receives a surprise visit from his father, Finn, just released from prison. Though Ivy has warned Ryan that her mother is trouble, he continues to date Laurel.', 40, '2010-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 19, 'Multiple Choices', 'As a result of falsely accusing her faculty adviser of sexual harassment, Naomi is now required to complete community service and publicly apologizes to her peers for the trouble she has caused. The gang is preparing for the SAT’s when Silver disagrees with Teddy’s decision to skip college to focus on his tennis career and things grow even more tense when she meets his movie star father, Spence. Liam and his father, Finn, reconnect and attempt to rebuild their relationship. Navid and Dixon host an underground gambling party that results in Dixon owing Mark a lot of money. Debbie reveals to Harry that she kissed another man, which forces the two to finally discuss their recent problems. Annie overhears their parents conversation and turns to Liam for support. Just when Naomi thinks her life is back on track, her evil sister Jen returns to Beverly Hills.', 40, '2010-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 20, 'Meet The Parents', 'Naomi and Jen are back to wreaking havoc in each others lives and just when Naomi thinks she has the upperhand, Jen slaps her back into reality. Teddy invites a nervous Silver to meet his father, Spence, for the second time and the meeting doesn''t go quite as planned. Adrianna struggles to write a new song for Laurel and turns to Navid for support, forcing Navid to realize he still has feelings for her. Adrianna records a duet with Javier Luna, a famous young pop singer, who quickly wins her over with his charm. Annie confronts Harry and Debbie about their recent marital problems, resulting in a family discussion about their future.', 40, '2010-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 21, 'Javianna', 'Adrianna''s new romance with pop star Javier continues to blossom, while Navid continues to work up enough courage to tell her how he feels. Jen has taken control of Naomi''s finances and puts her on a tight budget, resulting in an instant meltdown by Naomi. Without her credit cards, Naomi is too distracted to realize Liam is in need of support to deal with the departure of his father, so he turns to Annie for comfort. Despite Spence''s suggestion, Teddy refuses to end his relationship with Silver, and the two decide to spend the night together. Ivy invites Dixon to spend the summer in Australia with her and Laurel, but the idea doesn''t go over well with his parents. Harry and Debbie''s problems escalate when she finds out that Harry has been hiding Dixon''s gambling issues from her. Meanwhile, Jasper returns to resolve things with Annie.', 40, '2010-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 2), 22, 'Confessions', 'Annie and Liam test out the waters with his new boat, where they share their darkest secrets. Little do they know that someone is nearby and decides to share an explosive flame of gasoline with Liam''s boat. Liam finally tells Naomi their relationship isn''t working, leaving her more alone than ever. After a late-night dance, Naomi turns to someone for help, but he ultimately helps himself to her. Adrianna is offered the opportunity of a lifetime but is torn about the direction to take after Navid confesses his true feelings for her. Teddy discovers that Spence tried to bribe Silver and takes it upon himself to seek revenge in a most confrontational way. Ryan is delivered some mind-blowing news about his past with Jen when a mysterious package arrives on his doorstep, causing him to head down a disasterous path. Dixon and Ivy''s summer vacation plans in Australia comes to a screeching halt when he confesses to kissing Silver. Harry and Debbie face a major hurdle in their marriage when she learns the truth that he has been hiding in order to protect Dixon.', 40, '2010-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')), 3, 'Season 3', 'The third season picks up at the end of summer and focuses on the students senior year of high school. It follows Adrianna''s rise to fame, a new relationship between Silver and Navid and a confused Teddy who decides to reveal to his family and friends he is gay. It also deals with the aftermath of Naomi Clark''s assault.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 1, 'Senior Year Baby', 'In the season three premiere, Beverly Hills is rocked by an earthquake. Naomi has spent the summer dealing with the aftermath of her rape by Mr. Cannon, Annie and Dixon are dealing with the absence of their father while Debbie tries to hold the family together. Teddy and Silver find themselves happier than ever until he suffers an injury that could end his tennis career. Navid welcomes Adrianna back from her summer tour with Javier, but their arrival brings an unexpected death. Ivy and Dixon return from their summer vacation in Australia, while Annie and Liam discover their friendship may be best if it ends.', 40, '2010-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 2, 'Age of Inheritance', 'Naomi finds out she can now access the money in her trust fund, so she decides to throw a giant birthday party where The Honey Brothers perform a few songs. Dixon, Navid and Liam decide to take Oscar out for a night on the town...... but their party ends when Ivy finds a Facebook photo of Dixon doing a body shot off a girl. Annie has an instant connection with Charlie, a guy she meets at a coffee shop, but seems more interested in exploring her relationship opportunities with Liam. Jen is forced to go on bed rest until she delivers the baby and has no choice but to allow Ryan into her life. Silver confronts Teddy about his drinking problem.', 40, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 3, '2021 Vision', 'Naomi has constant flashbacks to her rape and begins taking sleeping pills in order to sleep through the night. Mr. Cannon invites Silver over to his apartment to watch his new documentary and secretly slips something in her drink. Meanwhile, Teddy wakes up from a night of drinking and realizes he hooked up with someone. Dixon learns that, despite what he assumed, Ivy is a virgin. Annie confronts her boss, Katherine about her awkward behavior and is shocked when she makes her an offer she may not be able to refuse. Adrianna sings a new stolen song at a memorial service but she soon regrets her decision to do so when the video goes viral on the web.', 40, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 4, 'The Bachelors', 'Silver plans a cancer-awareness charity event to honor her mother and enlists the help of Navid, Dixon, Liam and Teddy to appear in a bachelor auction. Ian, a theater student at West Bev, is brought in to help choreograph a dance number for the auction, but all comes to a stand-still when Teddy directs some negative words toward him. Annie and Adrianna discover the truth about Naomi and Mr. Cannon. Annie discovers Debbie’s financial problems and decides to take an offer to make some quick cash. Ivy and Dixon decide to spend the night together, but Dixon hits the brakes when Sasha returns with some life-altering news.', 40, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 5, 'Catch Me If You Cannon', 'Silver, Naomi and Adrianna craft a plan to seduce Mr. Cannon and prove that he raped Naomi, but they underestimate his ability to control the situation. Teddy and Ian are forced to do manual labor as punishment for fighting. Dixon fears for his life and pushes Ivy away, leading her straight into the arms of Oscar. A pregnant Jen seeks to hire a new assistant and Debbie applies for the job.', 40, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 6, 'How Much is That Liam in the Window', 'New parents Jen and Ryan find out about Naomi’s rape and Jen decides to take matters into her own hands. Ryan encourages Naomi to come forward even though his own job may be in jeopardy. Victor arranges a photo shoot for Adrianna and instructs her to go topless, while Navid and Silver watch in shock. Annie discovers that Charlie has a dark and disturbing side when she sneaks in to observe a staged reading of his play. Liam lands a job working shirtless in the window and on the sales floor of a clothing store. A mysterious customer offers him an opportunity he can’t refuse. Dixon apologizes to Ivy for breaking up with her but doesn’t realize that Ivy decided to lose her virginity to someone else. Oscar confronts Laurel and Ivy with shocking news about his past.', 40, '2010-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 7, 'I See London, I See France...', 'Ryan encourages Naomi to press charges against Mr. Cannon and prepares himself for the consequences. Oscar decides to set his sights on Naomi and unknowlingly helps her with the case against Mr. Cannon. Ivy decides to tell Dixon she slept with Oscar. Navid and Silver attend the Achievement Awards dinner while Annie, Teddy, Liam and Ian attend The Undies, an anti-achievement ceremony at the Beach Club.', 40, '2010-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 8, 'Mother Dearest', 'Adrianna has to un-invite Navid to her magazine premiere party after Victor arranges for her to go with Joe Jonas to boost her image. Annie and Dixon visit their dad but are shocked when a woman answers the door. A series of mishaps lead Jen to conclude that she is a bad mother, so she makes a decision with Ryan and her son''s best interest in mind. Naomi and Ivy team up to seek revenge on Oscar with a plan that involves skinnydipping in the Beach Club pool. Navid discovers that his father may be using underage girls in his porn films and convinces Silver to go undercover.', 40, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 9, 'They''re Playing Her Song', 'Teddy begins to feel more comfortable in his own skin and decides to visit a bar in West Hollywood where he soon realizes he forgot his wallet and is forced to turn to Ian for help. Annie is ready to take her relationship with Charlie to the next level but is mortified when his friends catch a glimpse of her in lingerie. Now a single father, Ryan turns to Debbie for help and the two end up hooking up. Navid deals with the fallout of having turned his father in for employing underage girls in his pornography business by turning to Silver. Adrianna is oblivious to Navid''s situation due to her new found fame.', 40, '2010-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 10, 'Best Lei''d Plans', 'Naomi jumps back into the dating world when she notices one of Ivy’s hot surfer friends, Zach, and tries to impress him by pretending to know how to work a surfboard. Ivy remains upset by her mother’s actions with Oscar and decides to rebuild her relationship with her father. Dixon and Annie decide to help Debbie get back into the dating world by signing her up for online dating, but while on her first date, she and Ryan sneak away for some one-on-one time at the Beach Club. While at the beach luau, Teddy gets jealous when he sees Ian with another guy and allows his feelings to control his actions. Navid and Adrianna’s relationship is strained now that she has found fame, which leads him closer and closer to Silver.', 40, '2010-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 11, 'Holiday Madness', 'Adrianna rents a mansion and decides to throw a housewarming party complete with an ice skating rink and elves. All is great in Adrianna''s world until Victor decides to reveal Adrianna''s secrets to the media. Annie decides to skip the party so she can take care of Liam, which leads to the two of them rekindling their old romance in Dixon''s bed. Ivy''s reconciliation with her father doesn''t go quite as she planned. Teddy and Ian discuss their feelings and decide to keep their relationship quiet for the time being, unaware that Dixon saw them share a kiss. Meanwhile, Navid and Silver share their feelings and realize they both feel the same way. Naomi returns home from the party to find an unexpected visitor.', 40, '2010-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 12, 'Liars', 'Naomi is taken hostage in her own home by an out-of-control Mr. Cannon who also lures Silver into the situation. Annie and Dixon’s cousin Emily from Kansas comes to town for an extended visit, but Emily immediately gets on Annie’s nerves. Dixon confronts Teddy about his kiss with Ian and promises to keep his secret. During surf practice, Ivy takes a nasty spill that makes her question her ability to compete in the surf competition. Adrianna’s world continues to crumble when she appears on a talk show to tell her side of the story, and she is blindsided by a surprise guest. Given Adrianna’s disastrous situation, Navid and Silver continue to keep their hook-ups a secret.', 40, '2011-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 13, 'It''s Getting Hot In Here', 'Naomi, Adrianna, Silver and Annie decide to have a girls’ weekend and head to a yoga retreat in Ojai. Annie attempts to be a good cousin and invites Emily along for the weekend but confronts her about being a downer on the trip. Emily purposefully neglects to wake Annie up for a sweat lodge session and uses the opportunity to turn the girls against Annie. Naomi, who originally thinks the retreat is silly, suddenly decides to extend her stay. Silver runs into Navid, and the two have a secret rendezvous. Adrianna returns from the retreat and calls a tabloid to sell an exclusive story. Meanwhile, Debbie plans a romantic dinner for Ryan, but they are interrupted by Dixon, forcing Ryan to quickly find a place to hide. Charlie realizes Annie has feelings for Liam.', 40, '2011-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 14, 'All About A Boy', 'Everything changes for Navid when he learns how Adrianna used the baby she gave up for adoption. Adrianna leans on Silver for support and makes a shocking discovery. Annie gets the opportunity to audition for a play and Emily comes up with a plan to sabotage her. Naomi returns from a spiritual retreat and decides to throw a party for Guru Sona but realizes the Guru may not be the person Naomi thinks she is. Ivy is nervous about getting back in the water after her accident. Teddy is being blackmailed and is surprised to find out who is behind it.', 40, '2011-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 15, 'Revenge With The Nerd', 'Navid and Dixon convince a music producer to shoot a music video at Shirazi Studios. Adrianna’s suspicions are confirmed, and she tells Silver about her plot for revenge. Emily distracts Annie and tries to get close to Liam, but her plan backfires. Teddy leans on Silver for support. Meanwhile, reality producers follow Adrianna and her friends around trying to shoot a pilot, and Naomi is surprised by her reaction to a nerdy lab partner who helps her out.', 40, '2011-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 16, 'It''s High Time', 'Back to her old tricks, Emily messes with Annie’s internship at the playhouse -- and with Annie’s boyfriend. Silver convinces Navid to sign the release for Adrianna’s reality show to help distract her and throw her off the track. Naomi bottles up her feeling for Max. After watching footage from her birthday party, Adrianna makes a stunning realization. Ivy meets a new guy, Raj and they strike up a friendship. Meanwhile, Dixon, Navid, and Liam take Teddy out on the town.', 40, '2011-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 17, 'Blue Naomi', 'Dixon and Navid formalize their partnership, and a chance meeting with Snoop Dogg could mean good news for Shirazi Studios. Naomi tries to impress Max by dressing up in an Avatar costume, but doesn’t quite get the reaction she was hoping for. After learning the truth about Navid, Adrianna vows to get revenge. Meanwhile, Annie and Liam work together to expose Emily, and Ray confides in Ivy.', 40, '2011-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 18, 'The Enchanted Donkey', 'When the group decide to take a vacation to Mexico for a much needed break, chaos ensues. Naomi brings her crush Max along, under the guise that she needs extra tutoring. Teddy encounters a former crush with surprising results, while Annie drags Liam around the city, determined to embrace the culture. Meanwhile, Silver and Adrianna’s bitter feud over Navid comes to a shocking confrontation.', 40, '2011-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 19, 'Nerdy Little Secrets', 'Naomi, sick of hiding her relationship with Max and afraid he might be cheating on her, follows him to an academic decathlon event, to confront him. Silver begins to behave erratically, which worries Navid and secretly pleases Adrianna. Raj helps Ivy overcome her fear of the water, while Annie starts working for lonely, aging actress Marla, and forms an unlikely friendship with her.', 40, '2011-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 20, 'Women on the Verge', 'Annie convinces Marla to attend a Hollywood movie premiere of one of Marla''s old films, while Ryan has an unexpected visitor and Teddy catches Marco in a lie and begins to wonder if he is being cheated on. Naomi finds out Max was accepted to a college in a different state, while Silver has a breakdown after receiving some upsetting news that causes Navid and Dixon to stage an intervention.', 40, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 21, 'The Prom Before the Storm', 'As the gang prepares for prom, Dixon and Annie learn some troubling news about their futures, and Ivy discovers that Raj''s health has taken a turn for the worse. With Silver away in the hospital, Adrianna tries to rekindle her romance with Navid. Meanwhile, Naomi and Max''s relationship is strained to the breaking point.', 40, '2011-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 3), 22, 'To the Future!', 'With graduation approaching, Naomi makes a decision that might prevent her from graduating with the rest of her class. Liam tells Annie that he doesn''t plan on going to college, and Ryan asks Debbie to move to Paris with him. An unplanned wedding springs up, but Adrianna isn''t invited after the group discovers her scheme to get revenge on Silver.', 40, '2011-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')), 4, 'Season 4', 'The fourth season of 90210 follows the group from West Beverly as they navigate life after high school. Their journey into adulthood will find them heading in different directions while trying to keep the same closeness that worked so well for them in high school. This tight-knit circle of friends will meet new people, resulting in friendships, relationships and loyalties being tested. Some will attend college, while others will start their careers. It''s a new and different time for them, as the stakes are much higher and there is a lot more to lose. Coming from a world of glamour and privilege, with endless possibilities in front of them, anything can happen. All in all, it''s just another day in the world''s most famous zip code. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 1, 'Up In Smoke', 'In the season four premiere, gang from Beverly Hills have graduated from high school. Naomi has spent the summer dealing with the shocking news of her pregnancy and quickly discovers she doesn’t have the status at college that she did in high school. Annie receives some unexpected news that keeps her in town, while Liam returns from his summer away ready to commit to Annie. Dixon finds himself without a roommate or a place to live, while an unexpected visitor tests Navid and Silver’s relationship after they move in together. Adrianna comes back to town looking for redemption, which she soon learns will be hard to earn back. Ivy and Raj struggle to deal with Raj’s health getting worse, while Teddy struggles with coming out to his family.', 40, '2011-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 2, 'Rush Hour', 'In an effort to re-gain her status, Naomi rushes a popular sorority, where she, along with Annie go through sorority games. Annie finds out a shocking secret about new guy Jeremy that could affect her future. Liam decides to keep the bar he bought on a whim and has a surprise guest from Alaska come into town, while Dixon finds an unlikely roommate in country boy Austin, which could lead to trouble. The search for Navid''s sister Leila forces Navid and Silver to enlist in Adrianna for help, much to the dismay of Silver.', 40, '2011-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 3, 'Greek Tragedy', 'After making an enemy in sorority president Holly, Naomi finds unusual allies who help her get revenge. Annie, short on money for sorority dues, must figure out a quick way to come up with the cash. Liam and Jane get closer, while Adrianna reveals a secret that causes Liam to look at her in a different light. Ivy becomes increasingly frustrated with her friends and lashes out at their lack of compassion, while Navid must deal with his uncle coming into town and trying to undermine Shirazi Studios.', 40, '2011-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 4, 'Let the Games Begin', 'Navid surprises Dixon with some studio time to apologize for messing things up with a music producer, where Dixon feels the pressure to create a hit song. Naomi plots revenge to take down rival Holly and her sorority during the Greek games, which requires Austin''s help, much to Naomi''s dismay. Silver directs a disastrous commercial for Liam''s bar, while Ivy feels torn between her relationship and her friends.', 40, '2011-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 5, 'Party Politics', 'Silver is asked to make campaign videos for political candidate Marissa Harris-Young who is running against Teddy’s Uncle Charles for public office. Teddy runs into an old flame and Annie gets stuck with Leila during an important date.  A surprise visitor threatens to tear Liam and Jane apart, while Naomi can''t shake her growing feelings for Austin during a party to encourage students to vote.', 40, '2011-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 6, 'Benefit of the Doubt', 'Liam gets offered a modeling job after an agent sees the commercial for his bar, while Annie finds herself starting to fall for an unlikely guy. During a charity talent show event to raise money for an experimental cancer treatment for Raj, Naomi is determined to win the contest in order to show up Austin''s out-of-town visitor Sally. While working on his music, Dixon pushes his limits and starts spiraling out of control, which forces Adrianna to confront him.', 40, '2011-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 7, 'It''s the Great Masquerade, Naomi Clark', 'Naomi  has to work with her arch-nemesis Holly to throw a campus costume party, leading to unfortunate consequences. Navid''s plan to bring down his Uncle Amal is threatened, while Silver discovers that political candidate Marissa Harris-Young is not who she seems. Meanwhile, Adrianna handcuffs herself to Dixon in an attempt to get him to stay sober and Annie must decide if she wants to give Patrick another chance.', 40, '2011-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 8, 'Vegas, Maybe?', 'The gang heads to Las Vegas, where Naomi meets Austin''s dad, country superstar Judd Ridge. The guys run into a celebrity at the pool, where Liam gets invited to play in a celebrity poker tournament. Teddy and Shane decide to tie the knot, while Dixon and Adrianna get closer. Meanwhile, Navid sees an opportunity to take his Uncle Amal down.', 40, '2011-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 9, 'A Thousand Words', 'Silver’s video of Teddy''s Vegas wedding is leaked to the press, and has damaging effects on his uncle’s campaign. Liam’s modeling career is taken to the next level by Shelia and Annie is determined to help Dixon, even though the help he needs comes at a high price. Meanwhile, Ivy and Raj decide to plan for the future.', 40, '2011-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 10, 'Smoked Turkey', 'Dixon tries to pursue a relationship with a resistant Adrianna, while Ivy and Raj’s arguing takes a toll on their relationship. Liam plans a holiday dinner for the gang, and an unexpected guest shows up. Meanwhile, Naomi goes to extremes to prove her love to Austin.', 40, '2011-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 11, 'Project Runaway', 'Dixon struggles with temptation as he tries to make his way back into the music world, while Annie confronts Jeremy, who stands in the way of her inheritance.  Naomi and Holly embarrass themselves in front of Janice Dickinson at a fashion show, while Navid reaches a breaking point with his uncle.  Meanwhile, Teddy makes a big decision that upsets Silver.', 40, '2011-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 12, 'O Holly Night', 'Naomi is asked by her new party planner boss Rachel to oversee her arch-nemesis Holly’s birthday party, while Annie breaks into Jeremy’s apartment in a desperate attempt to get the proof she needs to keep her inheritance.  Navid finds trouble after going with his Uncle Amal to make a deal with a potential buyer, and Liam discovers shocking news about Annie.', 40, '2011-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 13, 'Should Old Acquaintance Be Forgot', 'Naomi embarrasses herself in front of her boss Rachel in an attempt to get over her break-up with Austin. Dixon and Adrianna are booked to perform at a club, where they realize that working together might be a bad idea. Meanwhile, Silver takes her relationship with Greg to the next level and a party Annie throws ends up being a disaster because she is too distracted by Liam''s new relationship.', 40, '2012-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 14, 'Mama Can You Hear Me?', 'Naomi is determined to fix the relationship between her boss Rachel and her daughter Holly, which forces Holly and Naomi to work together. Greg asks Silver to move to New York with him and Navid finds out some shocking information about Greg’s daughter. Annie discovers Liam’s girlfriend Vanessa might have been involved with his motorcycle accident.', 40, '2012-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 15, 'Trust, Truth and Traffic', 'Annie has to make a decision that could expose her work as an escort when Dixon gets arrested in connection with a fire at a sorority house. Adrianna and Silver attempt to put their past behind them, which results in disaster for Silver''s relationship with Greg. Vanessa helps throw a party to re-launch Liam''s bar, where the All-American Rejects perform.', 40, '2012-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 16, 'No Good Deed', 'In an effort to put her inheritance to good use, Annie volunteers to organize a big charity fundraiser. When Naomi takes drastic measures to land her first event-planning client, her big plan back-fires. Meanwhile, Silver realizes she still has feelings for Navid, and Vanessa vows to make Liam a huge star after his agent drops him.', 40, '2012-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 17, 'Babes In Toyland', 'Naomi’s sister Jen arrives with her son for a surprise visit.  Adrianna and Dixon land a meeting with a major movie producer to discuss music on his next film, but are sabotaged by Vanessa.  Meanwhile, Silver gets accepted into New York University and Ivy attracts attention in the underground scene when she switches to a less conventional style of art..', 40, '2012-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 18, 'Blood Is Thicker Than Mud', 'Naomi is convinced that Annie’s new business partner P.J. is the perfect man for her, but discovers her sister Jen is also interested in him.. Adrianna and Dixon land a spot in a music festival, where Train performs and a record executive offers Dixon a recording contract. Adrianna tells Liam her suspicions that Vanessa staged the near drowning incident.', 40, '2012-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 19, 'The Heart Will Go On', 'Dixon collapses while arguing in the recording studio with Adrianna.  In the hospital, they run into Liam who is with Silver to support her during a test to detect if she has the breast cancer gene. Ivy finds out Raj still has cancer and is in the hospital, while Annie meets a new guy Caleb and discovers he is a priest.', 40, '2012-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 20, 'Blue Ivy', 'PJ proposes to Naomi and Annie discovers he needs to get married in order to get the rest of his trust fund. Dixon confesses to Navid that he signed a record contract but admits he did not tell Adrianna because the label didn’t want to sign her. Dixon also accepts a gig to play back up for Haley Reinhart, but doesn’t tell Adrianna. Liam asks Vanessa to move out and discovers she has emptied their joint bank account.', 40, '2012-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 21, 'Bride and Prejudice', 'Naomi’s friends worry that she is rushing to get married, so Naomi and P.J. decide to throw a small party so everyone can get to know him. Austin returns to Los Angeles and offers to be Adrianna’s new manager, suggesting she give country music a try. Caleb is concerned Ivy might not be emotionally stable, while Annie finally admits to Caleb that she is falling for him. Meanwhile, Silver feels conflicted about her feelings for Navid who is back in town.', 40, '2012-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 22, '''Tis Pity', 'Navid suspects that Liam and Silver hooked up so he decides to confront Liam on the red carpet of a movie premiere. Annie and Caleb fight their attraction to one another but finally give into temptation. Meanwhile, Naomi has been hired to plan the wedding of an heiress and discovers she knows the groom a little too well, and Austin enlists his dad, Judd Ridge to be help launch Adrianna’s country career.', 40, '2012-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 23, 'A Tale of Two Parties', 'A reluctant Naomi tries to sabotage the bachelorette party she has to host for Max’s fiancée Madison, where  Madison’s childhood crush, Nick Carter, makes a surprise appearance. At Max’s bachelor party, Liam and Navid get into a fight over Silver and the evening comes to an end with people at both parties getting hauled to jail. Meanwhile, Ivy blames Annie and Caleb for Diego having to go on the run.', 40, '2012-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 4), 24, 'Forever Hold Your Peace', 'Naomi shocks everyone when she announces she won’t be able to oversee Max’s wedding because she has accepted a job in New York and will be leaving immediately.  Teddy comes back to town and Dixon rushes back from touring to give his relationship with Adrianna another try, then fails to show up at their meeting spot.  Meanwhile, Silver feels like she has to choose between Navid and Liam and makes a life-changing decision.', 40, '2012-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')), 5, 'Season 5', 'The fifth and final season of 90210 finds the group struggling with the biggest issues of their lives. Having put their relatively carefree days at West Bev behind them and launched themselves into adulthood, they search for answers to the multiple cliffhangers of this year’s season finale with only their friendships to lean on. Life, death, love, loyalty, betrayal… and that’s just what to expect in the season premiere! There are some things money can’t buy, even in 90210.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 1, 'Till Death Do Us Part', 'In the season five premiere, Naomi and Max make some big plans that go horribly awry when they both get arrested and land in jail. Liam  is forced to put The Offshore up for sale in order to pay off Vanessa and buy out her $200,000 interest in Liam’s movie contract. Navid approaches Liam about becoming his business partner. Teddy is overwhelmed by Silver’s request to father her baby. Adrianna, unaware Dixon has gotten into a life-threatening accident, has an unforgettable evening in Las Vegas with a handsome stranger, Taylor, after she vows to get over Dixon and move on with her life. Annie asks Ade to return to Los Angeles to be with an unconscious Dixon, and the two girls decide to move into the beach house together.', 40, '2012-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 2, 'The Sea Change', 'Naomi and Max’s honeymoon plans are put on hold after Alec informs Max that his whirlwind wedding has caused a public relations problem and lowered their tech company’s stock price. Naomi decides to throw a high-class reception to reassure Max’s investors that their marriage isn’t a cause for concern. Adrianna discovers that club promoter Taylor, her one-night stand from Las Vegas, is partnering with Liam and Navid to re-launch The Offshore. Adrianna insists that their fling was a one-time thing, but Taylor suspects she has deeper feelings. At physical therapy, Annie and Dixon encounter fellow patient, Riley, who warns Annie to stop babying Dixon so he can learn how to manage on his own. At home, Dixon explodes on Annie and tells her that he’s tired of her help. Liam offers to buy out Vanessa’s portion of his movie contract, but Vanessa blackmails Liam to be her boyfriend again by threatening to show the police hidden camera footage of Liam. Silver invites Liam to be her date at Naomi’s reception, but gets a surprising answer. Liam confronts Vanessa after the reception, but their argument is cut short by a shocking accident.', 40, '2012-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 3, 'It''s All Fun and Games', 'Silver has yet to schedule her insemination appointment, and worries that she’ll no longer be attractive after undergoing the preventive surgeries. Adrianna encourages Silver to treat herself to an irresponsible day of fun doing all the things that she won’t be able to do once she becomes a mother. Alec ignores Naomi’s gestures to make nice, so Naomi poses as a wealthy investor and lures him to her yacht for a phony business meeting. The two reach an agreement to get along, and Alec spontaneously kisses Naomi, which she rebuffs. Alec apologizes, but Naomi insists on telling Max, unaware that Alec had planted the kiss to blackmail her. Meanwhile, Annie thinks that Riley is too hard on Dixon, but Riley insists that Dixon needs to change his attitude in order to accelerate his recovery. Liam learns that his video game contract can’t be finalized without Vanessa’s approval, so Annie encourages him to speak with her attorney, Lindsey Beckwith. Liam worries when a detective shows up asking questions about Vanessa’s whereabouts.', 40, '2012-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 4, 'Into the Wild', 'Naomi plans a romantic getaway with Max, intending to disclose that Alec kissed her, but when Max persuades Naomi to perform a trust-building exercise, she freaks out when she’s unable to complete it. Silver discovers that nude pictures from her photo shoot have been posted on the internet, and receives help removing them from Annie’s new prospect, Collin. Liam enrolls in Lindsey''s business law class, but she assumes he’s not serious about his education. Liam’s new costar, Kendall, is harassing him to begin a relationship with her for publicity, so Liam attempts to escape by going camping with Navid and Dixon. When Liam goes missing in the woods, Kendall seizes the opportunity to alert the media to find him. Meanwhile, Dixon encourages Adrianna to hire Taylor to create her new music video concept. After Taylor dares Adrianna to show him how sexy she can be, she realizes that she has feeling for him.', 40, '2012-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 5, 'Hate 2 Love', 'As Dixon continues to recuperate, Adrianna confides in Annie that she and Dixon are having intimacy issues. Annie grows closer to Colin, but Riley suspects that Colin isn’t who he appears to be. Colin discovers that Alex installed a GPS tracking app on Naomi’s phone so he can track her whereabouts, but Colin reconfigures her phone so she can secretly read Alec’s emails, which exposes Alec’s efforts to sabotage Max’s relationships. Navid hopes to show Silver how successful he’s become with the launch of the Pop Up, but he becomes suspicious that Silver and Liam are secretly seeing each other. Lindsey comes to the opening event to discuss Liam’s business plan, and their animosity gives way to passion.', 40, '2012-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 6, 'The Con', 'Liam and Lindsey  keep their  relationship under wraps, but when Navid''s jealous  streak gets the best of him, he arranges for Liam and Lindsey''s sex tape  to be shown in place of Liam''s movie premiere at Phenomi-com.  Riley  admits his feelings to Annie,  but Annie''s more interested in giving her relationship with Colin a chance.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 7, '99 Problems', 'When Adrianna opens at the Hollywood Bowl for a headlining artist, Dixon decides to buy her a celebration gift. Suspecting he might propose, Silver convinces Ade to come clean about her affair with Taylor. Annie confronts Riley about standing her up for wrongly suspecting that Annie is uncomfortable with his disability. Naomi encourages Max to hire an executive to replace Alec, but she’s uncomfortable when the perfect candidate-on-paper turns out to be a gorgeous girl, Bryce Albright. Liam receives a threatening letter that suggests the anonymous source knows the truth about Vanessa’s disappearance, and he’s relived when off-duty L.A.P.D. officer, Ashley Howard, becomes his bodyguard.', 40, '2012-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 8, '902-100', 'Naomi hosts an elaborate charity lingerie show at the Playboy Mansion in an attempt to gain membership status with the elite ladies West Beverly alumni group. Silver surprises her West Beverly High friends by performing burlesque at this stylish Homecoming event. Liam confides in Annie about Vanessa’s accident and tells Annie about the blackmail threats he’s received. Liam also accepts Navid’s apology for leaking Liam’s sex tape and offers Navid the chance to manage The Offshore. While Dixon is making big plans for Adrianna’s career on his new record label, he discovers that Ade had other desires aside from music.', 40, '2012-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 9, 'The Things We Do For Love', 'When Alex approaches Max about  forming a new company with him, Naomi intervenes by  attempting to persuade Bryce to rehire Max at  his company.  Naomi convinces Navid to take Bryce out  for drinks, and after a few cocktails Navid uncovers the truth about  Max''s termination, which leaves Naomi pondering the fate of her  marriage.  Then, Liam receives a blackmail letter about  Vanessa''s accident, and Annie agrees to lend him the money to help trap his blackmailer.  But  when Adrianna tells Ashley that she spotted Vanessa at the beauty salon, Ashley wrongly  suspects that Liam was headed for a secret rendez-vous with Vanessa.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 10, 'Misery Loves Company', 'Annie and Vanessa search for Liam after discovering that Ashley was falsely posing as his studio-hired bodyguard. Needing a break, Naomi goes on a road trip with Adrianna, only to have her wedding ring stolen. Meanwhile, Dixon fails to convince Megan he is over Adrianna.', 40, '2013-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 11, 'We''re Not Not in Kansas Anymore', 'Annie experiences an alternate reality about what life would have been like if she had stayed in Kansas, including being engaged to her high school boyfriend. In the alternate world, Dixon becomes a massively successful hip hop artist who no longer has contact with his family, while Adrianna is a washed-up actress and Hollywood’s bad girl. Naomi is a real estate agent, and Teddy has not revealed his true sexual orientation.', 40, '2013-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 12, 'Here Comes Honey Bye Bye', 'Naomi and Max see a marriage counselor to decide if they are going to stay married, while Teddy tells Silver he won’t ruin her chance to have a baby if she agrees to his terms. Navid uses Liam’s celebrity status to help him get into an elite secret society and Annie rushes to tell Riley her true feelings before he undergoes an experimental surgery.', 40, '2013-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 13, '#realness', 'Naomi and Max co-host a charity football game which re-kindles old feelings, while Navid pushes Liam to continue underground fighting. Adrianna purposely sabotages a performance so Dixon will let her out of her contract, and Annie’s blog gets the attention of a publisher.', 40, '2013-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 14, 'Brother From Another Mother', 'Liam experiences some symptoms of post-traumatic stress disorder while preparing to testify against Ashley, while Annie is furious when Naomi tracks down their half-brother Mark, a chef who owns a gourmet food truck. Silver is overbearing with her surrogate Michaela, whom Dixon discovers has an amazing singing voice.', 40, '2013-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 15, 'Strange Brew', 'Naomi decides to open a restaurant with her half-brother Mark, while Dixon books Michaela to perform at the restaurant opening, unbeknownst to Silver. Annie feels confused about her newly re-surfaced feelings for Liam and Navid agrees to escort Campbell’s fiancé to an event, only to find out Campbell is cheating on her.', 40, '2013-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 16, 'Life''s a Beach', 'Liam decides to open his own custom surfboard shop for women, but things get complicated when he becomes romantically involved with his first investor. Naomi tries to convince Mark to stay in Los Angeles after he receives an offer to be head chef at a restaurant in New York, while Dixon convinces Silver to direct Michaela’s first music video before she gets pregnant.', 40, '2013-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 17, 'Dude, Where''s My Husband?', 'Naomi meets up-and-coming mogul Jordan Welland, who hires her to plan events for his media empire, while Annie, Adrianna and Silver plan a girls’ night out for Naomi, which ends with disastrous results. Dixon starts to develop feelings for Michaela, and Liam finds out that the Cronus brothers plan to blame Navid for the cheating ring and is forced to befriend them to clear Navid’s name.', 40, '2013-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 18, 'A Portrait of the Artist As a Young Call Girl', 'Jordan asks Naomi to plan a launch party for the latest hot writer, known as Author X, which forces Annie to admit that she is Author X. Silver worries that Adrianna is not okay that she is dating Mark. Meanwhile, Dixon finds out that Michaela has feelings for Navid.', 40, '2013-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 19, 'The Empire State Strikes Back', 'Liam and Navid, in an effort to get teenage pro-surfer Cassie to be their first sponsored athlete, ask her favorite musician Olly Murs to do a special performance. Naomi travels to New York to make a good impression on Jordan’s mother, Cheryl with disastrous consequences. Annie decides to publicly say her novel is fiction but Dixon persuades her to tell the truth.', 40, '2013-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 20, 'You Can''t Win ''Em All', 'Jordan calls in a favor from his mother to help out Mark, but in exchange must end things with Naomi. Annie must deal with the betrayal Liam feels from being in her book and Michaela catches Navid and Adrianna during an intimate moment.', 40, '2013-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 21, 'Scandal Royale', 'Jordan''s sister Elizabeth gets into trouble with an out-of-control Royal, so Naomi helps out by taking the heat to protect Elizabeth''s reputation. Silver is called in to see her doctor about some test results and Annie decides to get over Liam by going to Paris for a book tour. Meanwhile, Adrianna performs after Fall Out Boy at a big event, but the concert ends in chaos.', 40, '2013-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1225901')) AND numero_temporada = 5), 22, 'We All Fall Down', 'In a memorable send-off, our favorite group from Beverly Hills will come together again after a traumatic event that makes them realize the importance of their relationships.', 40, '2013-05-13');
