INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 1, 'I Accidentally Vaporize My Pre-Algebra Teacher', 'Expelled from school, Percy Jackson unravels who he is, confronting a world of gods and monsters.', 39, '2023-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 2, 'I Become Supreme Lord of the Bathroom', 'Percy finds his place at Camp Half Blood, where he learns just how special his origins may be.', 44, '2023-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 3, 'We Visit the Garden Gnome Emporium', 'Percy sets off on the quest to return Zeus'' master bolt and stop a war between the gods.', 45, '2023-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 4, 'I Plunge to My Death', 'Our heroes search for a refuge in St Louis, and come face to face with the mother of all monsters.', 34, '2024-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 5, 'A God Buys Us Cheeseburgers', 'The quest deepens as Percy, Annabeth, and Grover are tasked with a favor from a fearsome opponent.', 40, '2024-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 6, 'We Take a Zebra to Vegas', 'Percy, Annabeth, and Grover must resist the alluring draw of a casino that feels outside of time.', 33, '2024-01-16');
