INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')) AND numero_temporada = 1), 8, 'The Prophecy Comes True', 'Mount Olympus beckons... and Percy must face his greatest battle yet.', 42, '2024-01-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12324366')), 2, 'Season 2', 'After Camp Half-Blood''s protective border is breached, Percy Jackson embarks on an epic odyssey into the Sea of Monsters in search of his best friend, the satyr Grover Underwood, and the one thing that may save the camp — the legendary Golden Fleece. Aided by demigods Annabeth Chase and Clarisse La Rue, along with his cyclops half-brother Tyson, Percy''s survival becomes the key to preventing Luke and the Titan Kronos from bringing down Camp Half-Blood — and, ultimately, Olympus.');
