INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 1, 'Ryomen Sukuna', 'After visiting his beloved grandfather in the hospital, Yuji Itadori encounters an apprentice sorcerer who demands that Yuji hand over a cursed relic.', 24, '2020-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 2, 'For Myself', 'Yuji manages to control the curse of Ryomen Sukuna. Later, he awakens in a room with Jujutsu High teacher Satoru Gojo, who offers him a deadly choice.', 24, '2020-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 3, 'Girl of Steel', 'Nobara Kugisaki joins the class on a trip to Roppongi where Gojo gives her and Yuji their first test: dispel a curse from an abandoned building.', 24, '2020-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 4, 'Curse Womb Must Die', 'When a curse womb attacks a juvenile detention center, Yuji''s group is called upon to rescue any remaining survivors — but combat isn’t an option.', 24, '2020-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 5, 'Curse Womb Must Die -II-', 'As Sukuna gruesomely holds Yuji''s body hostage, Fushiguro struggles against the sheer strength of Sukuna''s curse to buy time until Yuji can awaken.', 24, '2020-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 6, 'After Rain', 'Sukuna tells Yuji that he will bring him back to life on two conditions. Meanwhile, Suguru Geto and a cursed spirit discuss their plans for Gojo.', 24, '2020-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 7, 'Assault', 'The cursed spirit Jogo attacks Gojo, who has such little trouble fighting back that he leaves and brings back a student to observe the battle.', 24, '2020-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 8, 'Boredom', 'As Kugisaki and Fushiguro train for the exchange event, two older students from the Kyoto Jujutsu school arrive in Tokyo and pick a fight with them.', 24, '2020-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 9, 'Small Fry and Reverse Retribution', 'High schooler Junpei Yoshino finds his bullies horrifically killed in a movie theater. Sorcerer Kento Nanami and Yuji investigate the crime scene.', 24, '2020-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 10, 'Idle Transfiguration', 'Junpei gets some startling advice from Mahito. Later, Ijichi and Yuji track down Junpei and formulate a plan to set up a chance encounter with him.', 24, '2020-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 11, 'Narrow-minded', 'Annoyed at having to work off the clock, Nanami shows Mahito the true potential of his sorcery. Meanwhile, Yuji and Junpei bond over movies.', 24, '2020-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 12, 'To You, Someday', 'Ignoring Nanami''s warning, Yuji dashes into the school and tries to reason with Junpei, but Mahito soon interrupts. Yuji appeals to Sukuna for help.', 24, '2020-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 13, 'Tomorrow', 'Yuji and Nanami coordinate their attacks on Mahito, wearing him down. But as the cursed spirit approaches death, he finds a new power within himself.', 24, '2020-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 14, 'Kyoto Sister School Exchange Event - Group Battle 0 -', 'With the exchange event between the Tokyo and Kyoto Jujutsu schools set to begin, Gojo arranges for Yuji to make a surprise appearance.', 24, '2021-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 15, 'Kyoto Sister School Exchange Event - Group Battle 1 -', 'Shortly after the exchange event team battle begins, Todo ambushes the Tokyo students. Yuji moves to stop him but soon finds himself surrounded.', 24, '2021-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 16, 'Kyoto Sister School Exchange Event - Group Battle 2 -', 'Todo gives Yuji advice on how to better tap into his curse powers. After Kugisaki taunts Nishimiya, Panda fights the remote-controlled Mechamaru.', 24, '2021-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 17, 'Kyoto Sister School Exchange Event - Group Battle 3 -', 'While Miwa struggles to stand her ground against Maki''s attacks, Kugisaki chases down a flying Nishimiya, who lectures her about Mai''s hardships.', 24, '2021-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 18, 'Sage', 'Fushiguro dodges Kamo''s barrage of arrows but his opponent proves just as formidable in close combat. Meanwhile, Inumaki senses a foreboding presence.', 24, '2021-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 19, 'Black Flash', 'Inumaki, Fushiguro and Kamo struggle to hold their own against special grade cursed spirit Hanami, but Maki arrives to provide much-needed backup.', 26, '2021-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 20, 'Nonstandard', 'After analyzing Hanami''s assortment of skills with his self-proclaimed intellect, Todo uses his disorienting technique to attack in tandem with Yuji.', 24, '2021-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 21, 'Jujutsu Koshien', 'After the event''s interruption, the school tournament continues with a baseball match.', 24, '2021-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 22, 'The Origin of Blind Obedience', 'An investigation into a string of curse-related killings leads Yuji, Fushiguro and Kugisaki to the victims'' – and Fushiguro''s – former middle school.', 24, '2021-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 23, 'The Origin of Blind Obedience -II-', 'Fushiguro, Kugisaki and Itadori fight the cursed spirits on two fronts. When Fushiguro faces his enemy alone, he recalls his recent training with Gojo. He knows that he has to be able to surpass himself...', 24, '2021-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 24, 'Accomplices', 'Yuji and Nobara''s battle against the Death Painting Wombs Kechizu and Eso reaches its conclusion! However, even in victory there is a cost in killing, something the Jujutsu High students had never considered before. Meanwhile, Choso, Geto and Mahito gain wind of this event.', 24, '2021-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 25, 'Hidden Inventory', 'The jujutsu sorcerers Iori Utahime and Mei Mei are dispatched to an ominous manor where several people have gone missing. They infiltrate the manor and attempt to destroy the cursed spirit''s barrier, but suddenly the building starts to crumble.', 24, '2023-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 26, 'Hidden Inventory 2', 'Gojo and Geto are assigned to the mission of escorting and erasing the young girl compatible with the Tengen - the Star Plasma Vessel. Amanai Riko is being targeted by the Curse User Group Q, and the religious cult the Star Religious Group.', 24, '2023-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 27, 'Hidden Inventory 3', 'Gojo and Geto beat back the curse users after the bounty placed on Amanai''s head when her cell phone rings. A captured Kuroi is displayed on her phone. Gojo tries to bring Amanai back to Jujutsu High, but she insists on going to the negotiations herself.', 24, '2023-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 28, 'Hidden Inventory 4', '"Let''s go home, Riko-chan." The moment Geto extends a hand to Amanai, the worst that could possibly happen does. Geto is left dumbstruck as Toji Fushiguro makes his appearance. Toji then declares that he killed Satoru Gojo.', 24, '2023-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 29, 'Premature Death', 'August 2007. Gojo starts to handle missions on his own, causing Geto to, as well. One day a certain individual appears before Geto. What''s the conclusion that led to Gojo becoming the strongest jujutsu sorcerer, and Geto becoming the most evil curse user?', 24, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 30, 'It''s Like That', '2018. After finishing a mission one day, Itadori decides to go to the movies, Kugisaki decides to go shopping, and Fushiguro tells them he''s going home. After parting ways Kugisaki is approached by a woman who suddenly asks if she was with Itadori-kun.', 24, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 31, 'Evening Festival', 'The battle between Muta and Mahito continues and reaches its conclusion. Later, on October 31st, a veil is lowered over Shibuya and various jujutsu sorcerer teams assemble around the area.', 24, '2023-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 32, 'Shibuya Incident', 'Team Mei Mei are reassigned to a veil that has been lowered over Meiji Shrine Station. The team splits up and Yuji encounters a grasshopper curse assigned to protecting the veil. Elsewhere Satoru Gojo encounters Jogo, Hanami, and Choso.', 24, '2023-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 33, 'Shibuya Incident - Gate, Open', 'The battle between Satoru Gojo, Jogo, Hanami and Choso begins. Gojo informs Hanami that they will die first. Yuji encounters a woman who tells him that everyone was turned into monsters and boarded a train. As Gojo''s battle continues, the train arrives.', 24, '2023-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 34, 'Pandemonium', 'Now that Satoru Gojo has been sealed, Mechamaru works with Team Mei Mei to inform them about what is going on and has them work on enacting his plan on what to do now.', 24, '2023-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 35, 'Seance', 'Nanami, Fushiguro, and Ino meet up with Itadori, then Nanami issues new orders for the others to work together to lift the veil keeping sorcerers out.', 24, '2023-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 36, 'Dull Knife', 'Yuji and Megumi lift the veil that was keeping sorcerers from entering Shibuya. Nobara and Nitta encounter Shigemo and a battle ensues. Shigemo has the upperhand, but then Nanami arrives with the deaths of the assistant supervisors in mind.', 24, '2023-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 37, 'Red Scale', 'Yuji makes his way to Shibuya Station where he''s confronted by Choso. Choso unleashes his Convergence and the battle between him and Yuji commences.', 24, '2023-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 38, 'Fluctuations', 'Mei Mei and Ui Ui fight the Special-Grade Disease Curse summoned by whatever is pretending to be Suguru Geto. Meanwhile, Nanami joins up with Maki and Naobito, but they encounter a cursed spirit with unknown powers.', 24, '2023-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 39, 'Fluctuations (2)', 'Nanami, Maki, and Naobito are driven to the edge after the Special-Grade Cursed Spirit, Dagon, activates his Domain Expansion, Horizon of the Captivating Skandha. Fushiguro gives them a glimpse of a way to escape death, then Toji intrudes upon the fight.', 24, '2023-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 40, 'Thunderclap', 'Sukuna refuses to heed Jogo''s advice after waking up, instead displaying his overwhelming strength against the Special-Grade Cursed Spirit, Jogo. Meanwhile, Fushiguro faces off against the rampant Toji with neither being aware of the other''s identity.', 24, '2023-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 41, 'Thunderclap (2)', 'After being severely injured in his fight against Toji, Fushiguro suffers a surprise attack from Shigemo. On the verge of death, Fushiguro desperately heads toward Dougenzaka crossing and summons a certain Shikigami with his Ten Shadows Technique.', 24, '2023-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 42, 'Right and Wrong', 'Itadori reawakens with grievous resolve as he bears witness to the aftermath Sukuna has wrought upon Shibuya. Meanwhile, Nanami continues to fight through packs of transfigured humans in an exhausted haze until Mahito appears before him.', 24, '2023-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 43, 'Right and Wrong (2)', 'Itadori launches into a back-and-forth battle against Mahito, but he struggles against Mahito''s ploy of using average people against him. Meanwhile, Kugisaki encounters one of Mahito''s separated bodies as she returns to the battlefield.', 24, '2023-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 44, 'Right and Wrong (3)', 'Itadori stands in a daze at the disaster before his eyes, his mind already well past its limit. As a curse, Mahito is elated at seeing his ideal sequence of events play out before him, and he prepares to further finish off Itadori.', 24, '2023-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 45, 'Metamorphosis', 'After rescuing Itadori from his predicament, Todo bolsters his morale and encourages him to stand back up. As Mahito kicks things into higher gear, he begins using Soul Multiplicity and Body Repel to unleash omnidirectional attacks.', 24, '2023-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 46, 'Metamorphosis (2)', 'The moment it appeared Itadori and Mahito''s battle to the death was resolved, the being wearing Geto''s body asked, "Shall I save you, Mahito?" Itadori immediately recognizes the man before him as the very same one who sealed away Gojo and leaps to attack.', 24, '2023-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 47, 'Shibuya Incident - Gate, Close', 'Choso begins to realize the identity of the mastermind parasitizing Geto''s corpse as sorcerers gather for the final moments of the Shibuya Incident. The special-grade sorcerer, Yuki Tsukumo, comes to the rescue when they''re on the verge of death.', 24, '2023-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 48, 'Execution', 'While Yuji grapples with the weight of his sins, Naoya Zen''in and Yuta Okkotsu set out to execute him.', 24, '2026-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 49, 'One More Time', 'After fighting Yuta, Yuji learns his real objective. Megumi asks for Yuji''s help to save his sister.', 24, '2026-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 50, 'About the Culling Game', 'Itadori and his friends speak with Tengen about Kenjaku''s objectives and their plans for the Culling Game.', 24, '2026-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 51, 'Perfect Preparation', 'After going to collect their Cursed Tools, Maki awakens her true potential & slaughters the whole Zen''in Clan.', 28, '2026-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 52, 'Passion', 'Yaga is executed. Yuji and Fushiguro go to Hakari''s fight club hoping to meet him and recruit him.', 24, '2026-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 53, 'Cog', 'Fushiguro and Panda fight Kirara to try and persuade them while Yuji attempts to convince Hakari.', 24, '2026-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 54, 'Tokyo Colony No. 1', 'Yuji''s group enters two of the colonies and fight the Culling Game''s newbie hunters.', 24, '2026-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 55, 'Tokyo Colony No. 1 (2)', 'Yuji meets Higuruma and tries to persuade him, while Fushiguro is falsely led to Reggie.', 24, '2026-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 56, 'Tokyo Colony No. 1 (3)', 'Yuji Itadori fights Hiromi Higuruma.', 24, '2026-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 57, 'Tokyo Colony No. 1 (4)', 'Takaba handles the minions while Fushiguro has his showdown with Reggie.', 24, '2026-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12343534')) AND numero_temporada = 1), 58, 'Tokyo Colony No. 1 (5)', 'Fushiguro deploys his Domain Expansion in his climatic fight against Reggie.', 24, '2026-03-20');
