INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 1, 'The Myth of the House', 'Refaat''s old flame Maggie returns from Scotland, and he reluctantly invites her to a party in honor of his birthday. A sighting exacerbates the tension.', 52, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 2, 'The Myth of the Curse of the Pharaoh', 'After a supposedly cursed mummy is autopsied, a black cloud looms over Cairo. Refaat refuses to believe they''re linked — until a loved one is affected.', 47, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 3, 'The Myth of the Guardian of The Cave', 'When all fails, Refaat and Maggie search for a cure in the Libyan Desert. Joined by their ex-colleague, they must first get past a mythical creature.', 56, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 4, 'The Myth of the Naiad', 'After an alarming tarot reading, Refaat visits his hometown to resolve a family emergency. As he jumps to the rescue, an alluring voice hypnotizes him.', 49, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 5, 'The Myth of the Incubus', 'Overcome with grief, Refaat’s health deteriorates. Convinced that Shiraz is behind all tragedies, he chases her around a haunted maze in his dreams.', 45, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12411074')) AND numero_temporada = 1), 6, 'The Myth of the House: The Return', 'Refaat uses his brain''s faculties to decipher the real story behind Shiraz’s death, taking him back to where it all began.The third tarot card is shown.', 54, '2020-11-05');
