INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 1, 'Cowboy Gospel', 'After getting shortchanged on the fee for a bounty, Spike and Jet head to New Tijuana on the trail of another mark — but they''re not the only ones.', 51, '2021-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 2, 'Venus Pop', 'While chasing a bounty on a one-handed Venusian bomber, Jet and Spike grapple with rising interpersonal tensions, exacerbated by Spike''s secret past.', 40, '2021-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 3, 'Dog Star Swing', 'Jet needs cash to buy his daughter a birthday present. To get it, he and Spike track a potential bounty to a brothel, but Spike has his own agenda.', 47, '2021-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 4, 'Callisto Soul', 'When a group of ecoterrorists screw up her attempted shakedown, Faye enlists Spike and Jet to help her bring them in for the bounty.', 43, '2021-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 5, 'Darkside Tango', 'Jet reunites with his ex-partner to track down a recently released criminal. While he''s away, Spike and Faye try to pick up a quick job.', 46, '2021-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1267295')) AND numero_temporada = 1), 6, 'Binary Two-Step', 'When the Bebop needs repairs, Jet sends Spike to chase down a tip on a phantom bounty to cover the cost, leaving Faye to supervise the mechanic.', 42, '2021-11-19');
