INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')), 1, 'Season 1', 'A place where nothing ever gets done... small town government.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 1, 'Pilot', 'Indiana government worker Leslie Knope is given the assignment to convert an abandoned quarry pit into a community park. A documentary film crew follows Leslie through her mishaps and gaffes as she tries to make her assignment a reality.', 22, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 2, 'Canvassing', 'Leslie decides that she and her committee need to go door-to-door to gain support for the park project as well as support for an upcoming town hall meeting, but their mission does not go as planned. Meanwhile, Tom wanders away from the canvassing group and uses his own creative recruitment tactics.', 22, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 3, 'The Reporter', 'Leslie arranges for a reporter to do a story about her park project, but she and her committee have the worst time staying on topic. She then calls Mark to help her save the story, but it ends up hurting more than helping. Meanwhile, Tom does all he can to suck up to his boss.', 22, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 4, 'Boys'' Club', 'Leslie attempts to break into the political "old boy''s club," causing an ethical dilemma. Meanwhile, Andy plans a surprise for Ann.', 22, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 5, 'The Banquet', 'During a banquet honoring her mother''s public service, Leslie tries to convince a local zoning official to support her proposed park project. Meanwhile, Mark and Tom try to meet some ladies.', 22, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 1), 6, 'Rock Show', 'Leslie attends what she believes is a business meeting with an elderly local government bigwig, unaware that her mother has secretly set her up on a blind date. Andy plays his first gig since breaking both of his legs in the pit.', 27, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 1, 'Pawnee Zoo', 'When Leslie decides to marry two penguins to promote the local zoo, she inadvertently causes an uproar when both penguins turn out to be male. Meanwhile, Mark puts Ann in an awkward situation when he asks her to go see a movie.', 22, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 2, 'The Stakeout', 'While tending to the new community garden, Leslie and Tom discover someone has planted marijuana among the vegetables. In an effort to catch the people responsible, they pull an all-night stakeout. With Leslie''s permission, Ann decides to go on a date with Mark.', 22, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 3, 'Beauty Pageant', 'Leslie gets to judge a beauty contest, but ends up having conflicting opinions on "the ideal woman" with the other judges. While on a date with Mark, Ann learns Andy has been living in the pit.', 22, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 4, 'Practice Date', 'Leslie is nervous about her first date with Dave, so Ann takes her on a practice date to help her prepare. Meanwhile, after a local councilman is caught up in a sex scandal, Tom, Ron, April and Mark decide to see who can uncover the worst dirt on each other.', 22, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 5, 'Sister City', 'Leslie plays host to the Parks and Recreation department from Pawnee''s sister city, Boraqua, Venezuela, and is shocked at the cultural differences. Tom becomes an errand boy, and April plays hard to get.', 22, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 6, 'Kaboom', 'Leslie, Ann and the rest of the Parks Department volunteer to help the organization KaBOOM! build a playground for a neighboring town. After building an entire playground in one day, Leslie gets frustrated at the lack of progress with the pit, and takes some advice from Mark to cut through the red tape.', 22, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 7, 'Greg Pikitis', 'Leslie enlists the help of Dave and Andy in order to catch a local teen vandal. Meanwhile, Ann struggles to make her Halloween party fun, and ends up getting help from an unlikely source.', 22, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 8, 'Ron and Tammy', 'Leslie is upset when she learns the library department wants to take over her lot. Making matters worse, the library is run by Ron''s ex-wife Tammy, who still has a powerful emotional hold on him. Meanwhile, Andy gets a job in hopes of winning Ann back.', 22, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 9, 'The Camel', 'After one of the murals ("The Spirit of Pawnee") in City Hall is defaced, Leslie and the Parks Department compete to come up with a new design. Meanwhile, Andy and Ron share an uncomfortable moment at the shoeshine stand.', 22, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 10, 'Hunting Trip', 'Leslie tries to prove she can hang with the guys so she invites herself on Ron''s annual hunting trip, but things don''t go as planned. Meanwhile, April and Andy bond in the office while everyone is away.', 22, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 11, 'Tom''s Divorce', 'After Leslie finds out that Tom is getting a divorce, the department takes him out on the town to cheer him up. Meanwhile, Andy tries to hustle Mark in a game of pool.', 22, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 12, 'Christmas Scandal', 'Leslie designs the Pawnee Winter Wonderland Festival, but has to hide from the press when a meeting with a disgraced Councilman lands her in the middle of a sex scandal. Meanwhile, Ron offers to cover for Leslie for the day, and quickly discovers how much work she really does.', 22, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 13, 'The Set Up', 'Ann sets Leslie up on a blind date with a co-worker, which does not go as well as Leslie hoped. An old friend of Ann''s makes Mark feel insecure.', 28, '2010-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 14, 'Leslie''s House', 'After an amazing date with Justin in Indianapolis, Leslie tries to impress him with a dinner party at her house.', 22, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 15, 'Sweetums', 'The Parks Department forms a partnership with a local company to sell energy bars at the parks in Pawnee, but Leslie tries to stop the deal when she discovers how unhealthy the snacks are. Mark reluctantly agrees to help Tom move out of his house.', 22, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 16, 'Galentine''s Day', 'When Leslie hears her mom''s story about an old flame, she and her boyfriend Justin track him down and reunite them on Valentine''s Day. Meanwhile, Andy and his band are nervous about playing a gig at the Senior Center.', 22, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 17, 'Woman of the Year', 'Leslie is outraged when Ron wins a "Woman of the Year" award for a project she started. Meanwhile, Tom is desperate to find some money to invest in a local Pawnee club.', 22, '2010-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 18, 'The Possum', 'When a possum bites the mayor''s dog on a golf course, Leslie is asked to form a task force to catch the pesky animal. Meanwhile, Ron is upset when Mark refuses to bend the rules for him.', 22, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 19, 'Park Safety', 'After Jerry gets mugged by a bunch of kids, Leslie meets with the head park ranger in hopes of improving park safety. Meanwhile, everyone tries to be nicer to Jerry once he returns to the office.', 22, '2010-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 20, 'Summer Catalog', 'Preparing the Summer Events Catalog, Leslie decides to take Ron and the past directors of the Parks Department out for a picnic lunch. Tom enlists the help of Ann and Mark to pose for the cover photo.', 22, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 21, '94 Meetings', 'Ron is furious when April mistakenly schedules a ton of meetings for him. Meanwhile, Leslie fights to preserve a historical landmark.', 22, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 22, 'Telethon', 'Leslie hosts a late-night shift for a local telethon, and lands former Indiana Pacer Detlef Schrempf as a celebrity guest. Meanwhile, Mark has big plans for his relationship with Ann.', 22, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 23, 'The Master Plan', 'Leslie is disappointed when her new park plans are put on hold by a visit from two state auditors. April has plans for Andy at her birthday party, and Ann tries to piece together a romantic mystery.', 30, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 2), 24, 'Freddy Spaghetti', 'When Ben prevents Leslie from holding a children''s concert, she takes matters into her own hands. Mark makes some big decisions about his life, and Andy gets some unexpected romantic attention.', 26, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 1, 'Go Big or Go Home', 'Leslie and the Parks Department return to work after three months to discover that the budget crisis still looms. After unsuccessfully trying to have their budget restored by using Ann to charm Chris with a date, Leslie decides to make an all or nothing play by resurrecting the Pawnee Harvest Festival. Meanwhile, Ben restarts the youth basketball league and instates Ron and Andy to coach the only two teams. April returns from a vacation with a new boyfriend.', 22, '2011-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 2, 'Flu Season', 'While planning for the local Harvest Festival, Leslie is struck with the flu and is forced to go to the hospital. Ron and Andy have a day of male bonding, and Tom hits the spa.', 22, '2011-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 3, 'Time Capsule', 'Leslie wants to bury a time capsule that encapsulates life in Pawnee, but an odd suggestion from a local man causes unforeseen consequences. Andy seeks help from Chris about how to win back April.', 22, '2011-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 4, 'Ron & Tammy: Part Two', 'Tom tries to get back at Ron by going out on a date with Ron''s ex-wife Tammy, while Leslie tries to protect Ron from falling prey to her charms. Meanwhile, April is assigned to work with Chris.', 22, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 5, 'Media Blitz', 'While advertising for the Harvest Festival, Ben has to deal with some troubling questions about his past. Meanwhile, Andy continues to try to win April back.', 22, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 6, 'Indianapolis', 'Ron and Leslie take a road trip to the big city in order to visit Ron''s favorite place which happens to be a steakhouse, but Leslie has alternative motives for the trip.', 22, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 7, 'Harvest Festival', 'It''s make it or break it for the Parks Department at the Harvest Festival which is full of surprises.', 27, '2011-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 8, 'Camping', 'Leslie takes the whole department camping in order to brainstorm new ideas. Meanwhile, Andy attempts a romantic gesture for April, while Ann gets nervous when Chris returns to Pawnee as the new city manager.', 22, '2011-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 9, 'Andy and April''s Fancy Party', 'April and Andy host a dinner party for the Parks Department. Meanwhile, Ann tries to move on from Chris at a singles'' party.', 22, '2011-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 10, 'Soulmates', 'Leslie tries an online dating service, but doesn''t end up with a stranger as she expects. Also, Chris challenges Ron to a grilling competition as part of his plans to make Pawnee healthier.', 22, '2011-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 3), 11, 'Jerry''s Painting', 'Jerry''s contribution to Leslie''s community art show causes a stir. Ben moves in with April and Andy and attempts to teach them how to be adults. Meanwhile, Leslie is frustrated by Chris and his interoffice dating rules.', 27, '2011-04-28');
