INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 6), 4, 'Gin It Up!', 'Leslie tries to calm a minor scandal that gets blown out of proportion. Tom tries to impress a new love interest, while Ben convinces Ron to prepare a will.', 22, '2013-10-17');
