INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 6), 6, 'Recall Vote', 'Leslie prepares a haunted house with Ben, Ann and Chris for Halloween on the day of the recall vote. Meanwhile, Tom fears the end of Rent-A-Swag and persuades Ron to help save his business.', 22, '2013-11-14');
