INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1266020')) AND numero_temporada = 6), 11, 'Farmers Market', 'Leslie fights with Ben over questionable sales techniques at the local farmers market. Ann searches for a way to vent about the annoying aspects of pregnancy, while April supports Andy in a new creative venture.', 22, '2014-01-23');
