INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346'), 'Misterio');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346'), 'Suspense');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')), 1, 'Season 1', 'To fill your weekend with the suspending thought that will not leave your mind and open your eyes to the harsh reality of today’s society and the blind faith some people have in the so called guru’s of the society, MX Player brings you its latest series “Aashram”. Directed by Prakash Jha, The show features Bobby deol, Aaditi pohankar, Tushar pandey and Rajeev Siddhartharta. Bobby Deol plays the role of a Guru, known by the name of Baba Nirala, who is known to do magic, who has the solution to every problem of mankind and who has the knowledge of every missing woman of the area. And from crime to politics, this veteran Baba soon becomes the Godly man. Catch all the episodes of this thriller Hindi web show Ashram online only on MX Player.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 1, 'Pran Pratishtha', 'Pammi, the wrestling champion has always faced discrimination and tried her best to raise her voice against the system for the discrimination she has been a victim of, but to no avail. But then, like a ray of hope, Baba Nirala comes to her in the form of a saviour. And then, a body is dug out from a construction site in a forest. Stream the full episode of the latest Hindi web series Ashram online on MX Player!', 53, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 2, 'Grih Pravesh', 'The whole town is in rage when the skeleton is discovered in the forest and Chief Minister Sunderlal’s name comes up in the case. Sub Inspector Ujagar SIngh is assigned to the case and he has to reach the root of the matter. Pammi, on the other hand, is drawn to the magic of Baba Nirala’s devotion! Watch the full MX Originals’ latest web series Ashram in HIndi On MX Player!', 44, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 3, 'Duh Swapna', 'Pammi has decided to give up her career as a wrestler and follow the path of devotion and salvation under the guidance of Baba Nirala. She is highly impressed by the work Baba has done for the poor and the outcastes. Meanwhile the subinector Ujagar SIngh is probing the case of the skeleton. Will he find any lead in the case? All the episodes of the Hindi web show Ashram available on MX Player without signing up. Watch now!', 43, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 4, 'Sewa Daar', 'Baba has allowed Pammi to join the ashram as a sadhvi, but when her brother also shows interest to join the ashram, Baba is skeptical of him. While investigating the case of the skeleton, Ujagar Singh gets pushed towards the ashram and suspects some illegal activities going on there. With the growing popularity of Baba, CM is also inclined to find out his background. Will any secret information be revealed from Baba’s past? Stay tuned on MX Player to watch the latest Bobby Deol series Ashram online!', 45, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 5, 'Amrit Sudha', 'Baba Nirala has organized the event of Mass Marriage in the ashram, where Satti would be one of the grooms. The event is attended by Hukum Singh, who offers Baba a luring deal to participate in the upcoming elections. Ujagar Singh makes progress on the case when the skeleton gets identified by a girl and the story unfolds. Will Baba now enter the world of politics and accept Hukum Singh’s deal? Ashram, the latest Hindi show streaming on MX Player now!', 45, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 6, 'Vish Haran', 'Baba comes to know about I.G. Sharma’s investigation on him after the CMs orders and he lays a trap for him, to which he falls prey. Sub Inspector Ujagar Singh in his investigation has led him to a lead inside the ashram named Kavita, but it is impossible to reach her or talk to her. Will Kavita take the risk to contact someone outside the ashram? New Hindi web show Ashram full episodes, star cast, storyline, videos & more available on MX Player for free.', 44, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 7, 'Gati Rodh', 'Ujagar SIngh has dug too deep into the secrets of the ashram and he suspects that he might be near a big breakthrough. But then, he receives a call ordering him to stop the investigation on the case immediately and to not to pursue the case further. Bhopa, on the other hand receives shocking information about someone they had been following. Will Ujagar Singh give up the case? Watch the full MX Originals’ latest web series Ashram in HIndi On MX Player for free!', 42, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 8, 'Shuddhi Karan', 'Baba Nirala wants more support from the younger generation and for this, he calls the famous pop star Tinka Singh to arrange a music show in the ashram which he refuses flatly and also insults Bhopa. Meanwhile, Babita’s looks have created an impression on Baba and he tries to remove Satti from his way. What will Baba do now with Satti and pop star Tinka Singh? All the episodes of the Hindi web show Ashram available on MX Player without signing up. Watch now!', 45, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 1), 9, 'Maha Prasad', 'All the efforts of Ujagar Singh to continue the investigation have failed. He approaches his friend S. P. Dhandha and the two together decide to pursue the case in secret without letting anyone know. Inside the ashram, Satti has decided to do Shuddhikaran and is being transferred to somewhere else. Babita is shattered on learning this, and then late at night, she is called by Baba to his private quarters. Do not go anywhere, watch the full Hindi web series Ashram for free online on MX Player!', 47, '2020-08-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')), 2, 'Season 2', 'To fill your weekend with the suspending thought that will not leave your mind and open your eyes to the harsh reality of today’s society and the blind faith some people have in the so called guru’s of the society, MX Player brings you its latest series “Aashram”. Directed by Prakash Jha, The show features Bobby deol, Aaditi pohankar, Tushar pandey and Rajeev Siddhartharta. Bobby Deol plays the role of a Guru, known by the name of Baba Nirala, who is known to do magic, who has the solution to every problem of mankind and who has the knowledge of every missing woman of the area. And from crime to politics, this veteran Baba soon becomes the Godly man. Catch all the episodes of this thriller Hindi web show Ashram online only on MX Player.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 1, 'Triya - Charit', 'Tinka Singh is ready to organise the concert in Baba Kashipur Wala’s ashram. Tinka Singh’s concert in the ashram is a major buzz event and turns many heads towards the ashram. After the massive hit, the ashram comes into the public light and this is the best time for both CM Sunderlal and Ex-CM Hukum Singh, to make the most of it. Given the upcoming elections, the ashram soon becomes the epicentre of political discourse. While this happens during the day, baba Nirala makes sure to keep his nights busy as well', 39, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 2, 'Chhadma - Vesh', 'After getting what he craves the most, baba is impressed with Babita and he makes sure to show it. He orders the Sadhvi mata to let Babita perform the morning aarti every day. On the other hand, as the Tinka Singh concert becomes a massive hit and the subsequent events are even more cheered on, the demand for the narcotics has risen dramatically in the ashram premises. To meet the demand, Bhopa asks his assistant to buy more drugs. In a big win, inspector Ujagar along with Sadhu are able to pose as substance abusers and register in the aashram to carry out their investigation. Will Ujagar and Sadhu succeed in their mission?', 38, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 3, 'Naag - Paash', 'Baba Nirala takes CM Sunderlal to his Satsang. He also manages to make Babita strategically talk about how the ashram has given her a second life and transformed the lives of her and many other women like her. At the wrestling competition, the public demands baba to have a mock wrestle with Pammi. The latter understands that there is more than what meets the eyes and senses discomfort. What will she do now? Will she be convinced of baba’s real intentions? Will Ujagar and Sadhu be able to gather enough information before getting caught?', 32, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 4, 'Mrig - Trishna', 'After having wrestled with her, Pammi becomes the object of Baba Nirala’s next obsession. Next day, Pammi wakes up in pain and withers knowing that she has been molested, but remains unaware about who is behind the disgusting act. Akki makes friends with Sanober and decides to take her help in trapping Sunny. Will Pammi come to know about her perpetrator? Will Akki succeed in his plan to trap Sunny?', 40, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 5, 'Kaliya - Mardan', 'Inspector Ujagar and Sadhu are able to get a big win as they click pictures of the drug racket inside the ashram. On the other hand, oblivion the reality, a naive Pammi reaches the chambers of baba to inform him about being grotesquely assaulted in an unconscious condition. Baba Nirala assures her that he will order Bhopa to find her culprit as soon as possible. Will Ujagar’s cover finally be revealed? Will someone come to his rescue?', 36, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 6, 'Chhadma - Yudhha', 'Everyone in the ashram is taken by shock when they hear about sudden death in the ashram. Pammi calls her brother, Satti to inform him about her health but Babita takes the call instead and assures Satti that Pammi would be fine soon. Kavita tries to warn Pammi about Baba Nirala’s true face and tells her that he must be her culprit, but Pammi dismisses her. Ex-CM Hukum Singh takes on a public rally to demean the alliance of Baba Nirala and the current CM for his political gain. How will this end for him? Will Pammi see Baba’s truth?', 39, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 7, 'Moh - Bhang', 'After collecting enough evidence against Baba Nirala and proving all the illegal activities that are undertaken in the ashram, Natasha and Ujagar Singh hand over the file to the SP Dhanda. The SP uses the information to his benefits and gives the file to the CM in return for a much earlier promised transfer to Delhi. Pammi is determined to find out about baba’s truth and so she pretends to be intoxicated and unconscious. At the same time, Pammi’s father is on his way to meet her when he meets with an accident. Will Pammi be able to voice out the truth of baba? Will the CM expose Baba Nirala and his ashram?', 42, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 8, 'Koot - Neeti', 'Satti is on his way to the hospital after getting the news of his father’s accident. Pammi reaches the hospital too. She understands that Bhopa is behind her father’s accident and he has done it so that she keeps quiet about Baba Nirala’s real intentions. Pammi is also upset with Babita and confronts her about not telling her the truth of Baba Nirala. Having enough information to destroy the ashram, CM Sunderlal orders a raid on Baba Nirala’s ashram after not getting any cooperation from him. Baba Nirala is placed under house arrest.', 43, '2020-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 2), 9, 'Chakra - Vaat', 'Pammi devises a plan to keep a close eye on the guards and entry and exit points of the ashram. Right before the elections, Baba Nirala delivers the most awaited news and announces his alliance with Hukum Singh’s party in the upcoming elections. Baba Nirala is now promoted from messiah to a kingmaker in the eyes of the general public. While everyone is drowned in celebration, Pammi manages to run away and break free. Will CM Sunderlal expose Baba Nirala after losing the election? With public sentiment, political leanings and his followers by his side, Baba Nirala has now risen to immense power in the state. Will he ever see a downfall?', 52, '2020-11-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 1, 'Indra Prastha', 'With Hukum Singh coming to power as the Chief Minister of the state, Kashipur wale Baba Nirala has now emerged victorious as a King Maker. On the other hand, Hukum Singh feels powerless as only a handful of his supporters have been sworn in as ministers because Aashram is taking its own time to finalize the portfolios. The string of celebrations for victory at the elections continue - at the new and magnificent NIRALA DHAAM, but Baba Nirala seems far away from being content with all this glory. The Forces of Aashram and the state Government are constantly in search of Pammi, who had managed to escape from Aashram and is still on the run. Baba is restless and wants her back at any cost!', 46, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 2, 'Chakravyuh', 'A massive operation is mounted at Bodhi Ghat in order to nab Pammi. Aashram organizes a grand funeral for Satti and his father Gurusharan. Pammi and Akki are eventually spotted and attacked but amidst massive security and surveillance they manage to escape. Baba rages at Michael and Bhopa who tried to eliminate Pammi. Baba wants her alive and scratch free! Sadhvi Mata knows the perfect solution for Baba’s distress. She manages to coax the teenage daughter of the Dahiyas, and takes her to a Farmhouse where Baba is alone. On political front, Dilawar confronts Hukum and Bhopa as he feels betrayed for not being offered the Revenue Ministry. Babita grabs this opportunity and makes him an offer!', 49, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 3, 'Charan Kamal', 'A tense atmosphere spreads across Aashram when a young sewadar, from the Bada Mahulla community suddenly collapses during the Prabhat aarti at Dhyansthal, due to drug overdose. Komal spills the truth to her parents of being molested by Baba. Vipul Dahiya struggles to accept this dark truth as a lot is at stake. On the other hand, Baba and Bhopa decide to expand their drugs Business. Tinka and rocky help them set up their own Poppy Production.Pammi watches the news of her relatives being tortured in the village by the police, this breaks her heart. In the middle of the night, when Akki is fast asleep, Pammi goes to her heavily guarded village in order to surrender herself!', 47, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 4, 'Guru Dakshina', 'Komal and her mother try to lodge an FIR against Baba Nirala but SHO Haridas, dissuades them from doing so. Ujagar reaches out to the Dahiyas and offers to help them get Justice. Soon things go downhill and Vipul Dahiya finds himself in a fix in his battle to protect his daughter. Ujagar on other hand leaves no stone unturned in his investigation and prepares a water tight case against Baba Nirala. Bhopa sacks I.G Chauhan due to his incompetence - Bhopa finds the perfect solution to control Ujagar and Natasha - He gets Natasha’s Ex husband appointed as the DIG in Kashipur.', 38, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 5, 'Kaam Vatika', 'After losing his girlfriend Natasha and the water-tight case of the Dahiyas, a devastated Ujagar goes to visit his family. This visit opens a new door for Ujagar and he joins the Intelligence Bureau (IB). Pammi accuses Babita of selling herself to Baba Nirala. Hukum Singh’s special friend Sonia Hirawat, a big shot Image maker from London, arrives to help Hukum create a new Image for the Pradesh, but soon she learns who the real King is! Sonia decides to make the most of this opportunity for herself and Hukum as well.', 44, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 6, 'Swarg Lok', 'Baba’s vision of creating his own ‘Swarg Lok’ starts turning into a reality as Sonia executes a grand event where Baba takes avatar as BHAGWAN NIRALA. A new threat for Aashram rises from the Jungle of Karara as Ex-C.M Sunderlal manages to provoke the naxals who are against the encroachment of their forest land. As Bhagwan’s popularity spreads across the globe, Pammi gets more restless and decides to kill Baba. This reckless act of Pammi once again puts her and Akki’s life in Danger.', 45, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 7, 'Halahal', 'Bhopa offers Tinka a seat in Hukum Singh’s Cabinet. Baba turns down Banno’s demand of making their underage son a minister. Unwilling to give up, Banno approaches Hukum Singh, who makes her a better offer! Meanwhile Pammi and Akki who have taken shelter in a Basti, start posting letters to various Government authorities in order to seek justice. In the drugs investigation against Aashram, Ujagar and his boss Avinash Dubey are able to crack a link. After arresting the big broker Harry Ahuja, they succeed in arresting Tinka and Rocky, who are directly linked to Aashram and this illegal business', 44, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 8, 'Kuchakra', 'Ujagar’s investigation once again comes to a dead end after Tinka and Rocky are transferred to Judicial custody on the orders of the court. Bhopa gets the letters traced and raids the Basti to catch Pammi and Akki. In a rescue operation set up by Ujagar, Pammi and Akki safely escape to Delhi border. Pammi and Akki take shelter in outskirts of Delhi and with the help of Akki’s friend, Ravindra Rawat, they approach various News Channels to break Pammi’s story to the world.', 45, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 9, 'Shankh Naad', 'Trouble rises for Bhagwan Nirala as Akki manages to hack a popular TV Channel and Pammi’s video spreads like fire. Sonia immediately springs into action to do the damage control. District Judge Rastogi, who also saw Pammi’s video, takes cognizance of the matter and Bhagwan is summoned to appear in Court. Sunderlal grabs this opportunity and announces his support for Pammi. On the other hand pressure mounts on Hukum to get the district Judge transferred.', 36, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 10, 'Mahabhiyog', 'Sunderlal makes a deal with Baba which causes trouble for Hukum Singh as his Cabinet protests in ‘No Confidence’ vote . Banno comes to the rescue of Hukum and unfurls the past of Baba and Bhopa. She hands him the original FIR copies of cases on Monty Singh and Bhopa. Sunderlal’s lawyers back-out right before the hearing date but Ujagar manages to get a female activist lawyer Sunita, to fight Pammi’s case in the Court. The trial takes an unexpected turn when Bhagwan claims he is incapable of having sex as he has been castrated!', 47, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 11, 'Kopa - Bhavan', 'Baba Nirala frames Pammi for murder, ensuring her imprisonment. In isolation, the anger bews inside Pammi and she makes a decision to finally make Baba Nirala pay for all his sins. But in a shocking twist, Baba emerges as her savior, securing her release and welcoming her back into the Aashram. Is this a second chance or another deadly trap? Will Baba Nirala fall into Pammi’s trap and lose his empire?', 46, '2025-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 12, 'Prayashchit', 'Determined to free Pammi, Akki risks everything to infiltrate the heavily guarded Aashram. Meanwhile, an unexpected moment leaves Bhopa questioning his loyalties. Will his growing conflict change the game?', 36, '2025-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 13, 'Prem - Paash', 'As Bhopa gives in to forbidden desires, a secret affair begins to unravel within the Aashram’s walls. Meanwhile, Ujagar stumbles upon a witness whose testimony could finally expose Baba Nirala’s hidden sins. Will the truth finally surface?', 33, '2025-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 14, 'Kaala - Sach', 'Pammi masterfully drives a wedge between Baba Nirala and Bhopa, shaking the very foundation of the Aashram. But just when it seems like she’s winning, she makes a shocking choice—walking straight into Baba Nirala’s clutches. What is she planning?', 46, '2025-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12805346')) AND numero_temporada = 3), 15, 'Agni - Pareeksha', 'With Ujagar reopening the case, Pammi reignites her battle for justice. But can she take down the all-powerful Baba Nirala, or will she once again fall victim to his ruthless schemes? The ultimate showdown begins!', 43, '2025-02-27');
