INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 1, 'Out of the Deep Woods', 'Growing up in a remote forest cabin with his dad, Gus learns lessons about survival and the dangers that lurk beyond the fence to the outside world.', 55, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 2, 'Sorry About All the Dead People', 'Gus follows a reluctant Big Man into the unknown. Dr. Singh discovers what it will cost to save Rani. Aimee finds a new beginning after the world ends.', 50, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 3, 'Weird Deer S**t', 'Eager to send Gus on his way, Big Man figures out how to hide him in plain sight. The Singhs attend a neighborhood party that takes an ominous turn.', 43, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 4, 'Secret Sauce', 'Gus lands under the protection of some new friends as Big Man''s past catches up to him. Dr. Singh fears a nosy neighbor will unearth Rani''s secret.', 43, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 5, 'What''s in the Freezer?', 'Gus and Big Man pick up a traveling companion who suggests a perilous shortcut. Aimee''s sanctuary comes under threat. Time''s running out for the Singhs.', 40, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 6, 'Stranger Danger on a Train', 'In a moment of desperation, Dr. Singh makes a bold promise. A lost memento makes for a bumpy ride to Colorado. The Last Men close in on the Preserve.', 43, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 7, 'When Pubba Met Birdie', 'Gus''s quest to find Birdie and uncover more about her connection to his father leaves him questioning everything he''s ever known.', 39, '2021-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 1), 8, 'Big Man', 'His world shaken, Gus runs off and makes a rash decision. Big Man comes to grips with long-ago mistakes. Aimee makes a last stand against General Abbot.', 55, '2021-06-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')), 2, 'Season 2', 'Captured and imprisoned by the Last Men, a very special deer boy named Gus takes action to help his newfound hybrid friends escape before it''s too late.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 1, 'In Captivity', 'Locked up in the zoo''s kennels, Gus meets his fellow hybrid prisoners as he looks for a way out. General Abbot pressures Dr. Singh to produce a cure.', 58, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 2, 'Into the Deep Woods', 'An uneasy alliance forms over plans to free Gus and the other kids from captivity. Desperate for a breakthrough, Dr. Singh conducts a risky experiment.', 50, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 3, 'Chicken or Egg?', 'Gus'' expedition with Dr. Singh leads to several shocking discoveries. Big Man and Aimee seek refuge and reinforcements. Becky connects with a new friend.', 51, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 4, 'Bad Man', 'As Big Man reckons with sins of the past, Gus becomes a target of anger and suspicion, Rani''s misgivings multiply, and Becky begins basic training.', 58, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 5, 'What It Takes', 'General Abbot makes an example out of Gus. Dr. Singh obsesses over his research ahead of an important presentation. Becky crosses paths with a frenemy.', 52, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 6, 'How It Started, How It''s Going', 'The zoo turns into a battle zone when the rescue mission takes flight, with families coming together — and falling apart — during the chaos.', 43, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 7, 'I''ll Find You', 'After an eventful, obstacle-strewn journey to find a safe haven, Gus learns more about his origins and how far Birdie was willing to go to protect him.', 55, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 2), 8, 'The Ballad of the Last Men', 'Warned about General Abbot''s plans, Gus and his friends prepare to take a stand and defend the hybrid kids, no matter what it takes.', 57, '2023-04-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')), 3, 'Season 3', 'In this final chapter, Gus and his friends embark on a harrowing journey in hopes of curing the Sick — and finally discovering the truth about hybrids.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 1, 'The Beginning Is Also the End', 'Gus and his cohorts set out for Alaska to reconnect with Birdie, who''s working on a cure for the Sick. But first, they test their luck at an old casino.', 48, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 2, 'Thank God I''m a Country Boy', 'After a doctor joins Gus and his crew, they seek a way to the coast and stumble upon a plane owned by a family in desperate need of medical attention.', 47, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 3, 'The Pack', 'As Gus learns more about a threat and their dangerous plans, the group races to catch a departing boat. Jepperd and Becky face an impossible decision.', 46, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 4, 'Beyond the Sea', 'An unsettling discovery at sea forces Gus to take on a grim chore as tensions swell between his companions. On land, an enemy interrogates Becky.', 51, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 5, 'The Tail-Tale Heart', 'As polar night looms, Gus and his crew arrive at the outpost — but they''re not alone. To find Birdie and the cave, they must brave several obstacles.', 44, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 6, 'Here, There Be Monsters', 'After a daring rescue, Gus meets an individual well-versed in hybrid history. Amid emotional reunions and eerie revelations, all roads lead to the cave.', 47, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 7, 'The Road Ends Here', 'With loved ones beside him, Gus goes on a treacherous journey into the cave to find a cure once and for all. Meanwhile, chaos breaks out at the outpost.', 49, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt12809988')) AND numero_temporada = 3), 8, 'This Is a Story', 'After suffering an unimaginable loss, Gus must make a choice that will determine the fate of humans and hybrids. Who will be left to tell their story?', 50, '2024-06-06');
