INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')), 1, 'Season 1', 'When their hidden base comes under attack, a band of civilians and military personnel escape through a Stargate on an ancient ship headed into deep space. Now, these survivors must figure out a way to get back to Earth, while also providing themselves with the most basic of needs - food, water and air.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 1, 'Air (1)', 'When Icarus Base is attacked, it''s inhabitants are forced to flee through the Stargate. The base was created on a distant planet to take advantage of a powerful energy supply located there. Their goal is to try and determine the purpose of the mysterious ninth symbol of the Stargate which they have never been able to lock in. In going through the Stargate, they are transported not to Earth but onto an very old, apparently uninhabited but huge spacecraft. With the group''s commander injured, Lt. Scott and the chief scientist, Dr. Nicholas Rush lead the exploration of the craft. Several areas of the ship have been damaged but it is basically functional. They are able to learn that they are in fact billions of light years from Earth.', 44, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 2, 'Air (2)', 'The survivors arrive on an uninhabited ship floating billions of light years away from Earth. Panic spreads throughout the group and Col. Young, who was severely injured during the escape, transfers command to Lt. Matthew Scott, before lapsing into unconsciousness. Teams led by Dr. Rush and Sgt. Greer try to make sense of the situation, while Lt. Tamara Johansen, a medic who was days away from leaving the program, is thrust into the role of chief medical officer.', 45, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 3, 'Air (3)', 'With the air supply failing on the Destiny, a team disembarks to a desert-like planet in search of the mineral needed to scrub the ship’s air of carbon dioxide. After testing numerous sand samples without success, and with their window of opportunity closing fast, the group opts to split into two to cover more ground, despite the unbearable heat.', 44, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 4, 'Darkness', 'The Destiny suffers a power crisis, putting the lives of the stranded crew in jeopardy and forcing them to consider abandoning the ship.', 44, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 5, 'Light', 'With the ship on a collision course, the crew must decide who will stay and who will flee on the shuttle to try and find a habitable planet.', 44, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 6, 'Water', 'Severe rationing can''t save the Destiny''s dwindling water supply, forcing Colonel Young and Lieutenant Scott to seek out drinkable water on a deadly ice planet.', 44, '2009-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 7, 'Earth', 'With the situation onboard the Destiny dire, General O''Neill and Home World Command orders Col. Young to execute a high risk plan concocted by the I.O.A. scientists which, in theory, could return the crew to earth.', 44, '2009-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 8, 'Time', 'Visiting a newly discovered jungle planet, the crew is amazed to recover a Kino by the gate. Downloading the Kino data, Eli discovers video of the team, which appears to have been shot during an earlier visit. The mystery of the video’s origin becomes a secondary concern as members of the team start falling ill.', 44, '2009-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 9, 'Life', 'Aboard Destiny, Dr. Rush supervises the exploration of new areas of the ship. Looking for resources to make their everyday lives easier, the crew stumbles upon a piece of Ancient technology that carries the promise of a way home. While somewhat familiar with the find, Dr. Rush can’t guarantee the safety of using it, bringing him and Col. Young to a standoff on what to do.', 44, '2009-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 10, 'Justice', 'Everyone is shocked when a member of the crew is found dead from a gunshot wound. While at first glance it appears to be suicide, the gun is nowhere to be found. The crew is confined to quarters while a search is performed and when the gun shows up in Col. Young’s quarters, he becomes the number one suspect.', 44, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 11, 'Space (1)', 'A snafu with the communications stones lands Col. Young''s consciousness in an unknown being, resulting in a standoff between the Destiny and an alien vessel and the abduction of Chloe.', 44, '2010-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 12, 'Divided (2)', 'Dr. Nicholas Rush and Chloe suffer nightmares following their ordeal on the alien vessel, and Rush suspects that a tracking device may have been placed on the ship''s hull. Later, a splinter group on Destiny executes a coup with life-threatening consequences.', 44, '2010-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 13, 'Faith', 'Now firmly in control again, Col. Young and the other military personnel try to find a way to live with the civilians who tried to take control of the ship. When the Destiny prematurely drops out of FTL due to a computer glitch, they find both a sun and an Earth-like planet that should not be there. Rush concludes that the entire system was created by an alien race that is far beyond their imaginations. With the ship malfunctioning and a month''s worth of repairs before it can jump again, several of the military and civilians decide to spend time on the planet. Hard feelings from the mutiny persist and it''s an opportunity for everyone to mend fences. When the time comes to return to the Destiny, several of them decide they want to stay on the planet. Young is prepared to let them stay, but he imposes severe conditions.', 44, '2010-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 14, 'Human', 'Dr. Rush relives his past life by sitting in the alien chair in an attempt to download critical data. A university professor, his wife''s cancer returns and he is recruited by Dr. Daniel Jackson for what will be called the Icarus project. He''s avoiding dealing with his wife''s situation and throws himself into his work. In his dream-like state, he''s trying to make sense of all the information he is accumulating. Back on the ship, the Destiny drops out of FTL and some of the crew investigate the planet below. They find an ancient archaeological site but are trapped when part of the site caves in. Digging them out is a slow process and the next jump is quickly approaching.', 44, '2010-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 15, 'Lost', 'Still trapped on the planet after the Destiny has jumped, Lt. Scott, Sgt. Greer, Chloe and Eli try to find a way out of the underground maze. After one is caught in another cave in, the remaining three make their way to a gate but must jump blindly from planet to planet hoping to pick up a signal from the Destiny before it jumps. On board the ship, Col. Young decides to send out a search party. The clock is ticking down and the next jump will take them into an inter-galactic void forever leaving their friends behind. TJ meanwhile decides the time has come to tell Col. Young that she is pregnant with his child.', 44, '2010-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 16, 'Sabotage', 'The Destiny has jumped into hyperspace and is now traveling through an inter-galactic void. They''ve also been unable to locate Eli, Chloe and Scott who have been left behind. Dr. Rush has calculated that based on their current energy consumption, the Destiny has insufficient fuel to reach the next galaxy and they are doomed to die. The engines suddenly fail however and they arrange for an expert, Amanda Perry, to come on board via the communication stones and help them out. Perry and Rush have known each other for many years but as a quadriplegic, is experiencing what life has to offer. On Earth, Camile Wray''s consciousness has been transferred to Perry''s body and is wheelchair bound.', 44, '2010-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 17, 'Pain', 'Lt. Tamara Johansen tries to track down what is causing the crew to hallucinate.', 44, '2010-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 18, 'Subversion', 'Earth''s Stargate Program isn''t the only group in the Milky Way that''s interested in the Ancients'' Destiny. What''s worse, this long-time foe may have a spy among those closest to the Icarus project.', 44, '2010-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 19, 'Incursion (1)', 'An enemy from the Milky Way has boarded the Destiny and has taken hostages. Is it possible that they know how to get back or have they stranded themselves as well?', 44, '2010-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 1), 20, 'Incursion (2)', 'As Young and Camille attempt to resolve the hostage crisis with Kiva, Destiny suffers from power fluctuations and blackouts due to its proximity to a binary pulsar.', 44, '2010-06-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')), 2, 'Season 2', 'The Destiny continues its journey through the Universe, while its crew suffers from a lack of supplies and no knowledge of its final destination. Struggling to control the ships systems, tempers and personalities of the crew clash. Facing uncharted space and enemies who would take the ship by force, the Destiny crew persevere in their struggle to stay alive and find a way home.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 1, 'Intervention (3)', 'Everett and the crew continue their efforts to save Destiny while holding off the Lucian Alliance invaders.', 43, '2010-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 2, 'Aftermath', 'Desperate for food and water, Rush directs the ship to a planet that has been locked out of Destiny''s controls. Young and Wray clash over what to do with the Alliance prisoners.', 44, '2010-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 3, 'Awakening', 'The crew encounters a ship remarkably similar to Destiny, which may hold the key to their returning home.', 44, '2010-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 4, 'Pathogen', 'Chloe behaves in a bizarre way, prompting a search of her quarters, where Lt. Scott finds a journal penned in an alien language. Elsewhere, Eli copes with his mother''s medical condition.', 44, '2010-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 5, 'Cloverdale', 'When Scott''s team explores a new planet, a plant-like organism infects the lieutenant, causing him to hallucinate a life back on Earth where he is getting married.', 44, '2010-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 6, 'Trial and Error', 'Young is plagued by mysterious dreams where Destiny is destroyed by alien attackers no matter what he does.', 44, '2010-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 7, 'The Greater Good', 'Rush and Young investigate an abandoned alien craft which is just outside the Destiny. While they do this, the crew onboard the ship find the bridge and discover that Rush is responsible for the countdown clock not activating when the ship emerges from FTL.', 43, '2010-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 8, 'Malice', 'Simeon makes his escape from Destiny, sending Nicholas Rush on a vengeful mission. But Young and Greer attempt to retrieve Simeon unharmed.', 44, '2010-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 9, 'Visitation', 'Members of the crew left behind in another galaxy make a shocking return to Destiny.', 43, '2010-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 10, 'Resurgence (1)', 'The crew''s new-found control over Destiny''s flight path introduces new risks when they find themselves in the middle of a war between two races.', 43, '2010-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 11, 'Deliverance (2)', 'Locked in a battle with a Drone Command Ship, the Destiny is surprised by the arrival of the Aliens that abducted Rush and Chloe.', 44, '2011-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 12, 'Twin Destinies', 'Rush travels back in time to avert a disaster, meeting a past version of himself.', 43, '2011-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 13, 'Alliances', 'Camille and Sgt. Greer are trapped when Homeworld Command comes under attack.', 44, '2011-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 14, 'Hope', 'Chloe''s body is taken over by another consciousness. Meanwhile, Dr. Volker is stricken with a mysterious illness.', 44, '2011-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 15, 'Seizure', 'Rush slips into a coma in the neural interface chair, and Amanda connects with him in the ship’s matrix, but Ginn informs Eli of a problem with that scenario. Elsewhere, Dr. Rodney McKay’s plan to dial the ninth chevron address hits a snag.', 43, '2011-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 16, 'The Hunt', 'An alien creature attacks an exploration team from Destiny, taking two crew members captive.', 44, '2011-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 17, 'Common Descent (1)', 'Destiny comes upon a colony where the people claim their civilization was founded two thousand years earlier ... by Destiny''s crew.', 43, '2011-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 18, 'Epilogue (2)', 'While attempting to return a group of colonists to their home, the crew finds that the planet is on the verge of seismic destruction.', 44, '2011-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 19, 'Blockade', 'The Destiny needs to be refueled but every time they come out of FTL the drones seem to be waiting for them. It''s not obvious how the drones know they''re there but it doesn''t matter a great deal since they only have one more try before running out of fuel completely. Eli suggests they go through a blue supergiant star, though the heat it creates might destroy the ship. They have little choice so Col. Young evacuates everyone to the only planet available with the exception of Eli and Rush. Lisa also stays behind to collect some of the medicinal herbs they''ve grown only to be trapped just as the Destiny goes through the star. On the planet, Young and the others find evidence of a destroyed civilization - and the drones.', 44, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1286039')) AND numero_temporada = 2), 20, 'Gauntlet', 'Eli and Rush have found a way to identify the location of drone mother ships using the Destiny''s long range sensors. The bad news is that the Drones seems to be awaiting them at every possible stop along Destiny''s path. They find a temporary solution to neutralize the mother ships but realize that they cannot engage in a major battle every time they need to re-supply. Eli suggest that they use the stasis pods for the crew and jump to the next galaxy, a trip that will take three years. All goes well until they realize that one of the pods has been damaged and one person will have to stay behind in the hopes of fixing the unit in the short time available or die.', 43, '2011-05-09');
