INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 1, 'Countdown', 'Unsettling events put a group of brilliant friends on edge as a mystery unravels with origins tracing back to China during the Cultural Revolution.', 61, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 2, 'Red Coast', 'Auggie''s countdown jeopardizes her nanotech work. Jin becomes engrossed in an otherworldly VR game. Ye Wenjie follows through on a radical idea.', 64, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 3, 'Destroyer of Worlds', 'Obsessed with their virtual reality quest, Jin and Jack race to solve a complex riddle — but advancing to the next level brings harrowing consequences.', 54, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 4, 'Our Lord', 'Jin seeks justice after a death rattles the group. Investigators learn of an extremist group devoted to an otherworldly entity ahead of a major summit.', 45, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 5, 'Judgment Day', 'As threat levels rise, a secret mission to retrieve enemy intel ventures into dangerous territory. An ominous message reaches Earth.', 58, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 6, 'The Stars Our Destination', 'With the world in a state of panic following a momentous declaration, Wade gathers the world''s greatest minds to prepare a defense plan.', 49, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 7, 'Only Advance', 'A bold proposition for the Staircase Project puts the group at odds. Will weighs his options. Ye returns to a familiar place.', 59, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13016388')) AND numero_temporada = 1), 8, 'Wallfacer', 'A high-level operation upends Saul''s life. With emotions and expectations high, the probe launches into space as humanity enters a daunting new era.', 57, '2024-03-21');
