INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 1, 'Take Your Daughter to Work Day', 'With his retirement from the CIA imminent, Luke prepares for his next adventure, but revelations at home and an urgent matter at work upend his plans.', 55, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 2, 'Stole Train', 'Forced to team up in order to take down Boro, Luke and Emma realize their newly strained relationship is only the start of their problems.', 46, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 3, 'Honeyplot', 'The team goes from averting an international crisis to seeking sensitive intel in Moldova, where Emma offers to lure a target when complications arise.', 55, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 4, 'Armed & Dane-gerous', 'After receiving reassurance from Luke, Emma comes home to a startling surprise. In Greece, the team takes on a risky mission to break out a trusted ally.', 57, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 5, 'Here Today, Gone To-Marrow', 'Amid a devastating family emergency, Luke finds the lines of his double life becoming blurry as he deals with a distracted Emma and a demanding Boro.', 57, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 6, 'Royally Flushed', 'Barry and Tina infiltrate a private, high-stakes card game in hopes of inching closer to Boro. Emotions boil over when the team gets trapped in a bunker.', 59, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 7, 'Urine Luck', 'While closing in on Boro, Luke and Emma juggle relationship drama and a highly delicate situation. A life-or-death matter forces Roo to find a release.', 52, '2023-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 1), 8, 'That''s It and That''s All', 'With the clock ticking, Luke and Emma make tough choices to finish the mission and stay alive. A big day for the Brunner family spirals out of control.', 46, '2023-05-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 1, 'Fullest House', 'It''s a sink-or-swim mission when Luke and the team dive into deadly waters to stop a sinister terrorist from making a massive splash.', 49, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 2, 'Highly Re-Greta-Ble', 'A face from the past threatens Luke and Tally''s recharged romance. The team breaches a fortified compound to keep vital intel out of enemy hands.', 49, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 3, 'Tango and Smash', 'As Greta attempts to loosen Luke''s lips, the safe-house gang gets an earful from afar. Emma turns heads on the dance floor with an unlikely date.', 46, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 4, 'Astro-Not', 'While Cress tightens the screws, Chips matches wits with an interrogation expert. A stealth mission makes a bigger bang than expected.', 47, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 5, 'Trippin'' the Abyss', 'Barry hitches a ride to the final frontier. As an operative''s cover story begins to crumble, Luke and Emma seek help from an unexpected ally.', 50, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 6, 'Penny Possum''s Pizzapocalypse', 'Emma and Luke catch a buzz in a deep-sea submersible. Back on land, bullets and breadsticks fly in a confrontation at a pizza joint.', 50, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 7, 'Dam It', 'Every second counts as the team scrambles by land, air and sea to avert a catastrophe. Aldon finds himself outnumbered — but not outmatched.', 42, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt13064902')) AND numero_temporada = 2), 8, 'Let''s Twist Again', 'As the clock ticks down to zero hour, Luke and the crew must break into a top-secret facility before their adversary turns off the lights — for good.', 49, '2025-06-12');
